/* ===========================================================
   ingles4/unit12.js — Inglés 4 · Unit 12: Senses and memories
   Estructura: sections[] → activities[] → { type, ...datos }
   Tipos disponibles: notes, flashcards, match, mcq, dictation,
   dialog, speaking, stress, reading, fix, soft, comment, order, roleplay
   Fuente: resúmenes oficiales Evolve (Vocabulary / Grammar /
   Functional language summary) — sin ejercicios del alumno.
   =========================================================== */
(() => {
  /* ---------- Vocabulario base ---------- */
  /* Lesson 1 · Talking about the senses: [palabra, def ES, def EN corta, ejemplo del curso, pregunta, sentido] */
  const SE = [
    ['bright', 'brillante, luminoso (adj.): lleno de luz o que brilla con fuerza; también de color fuerte y claro', 'full of light or shining strongly; having a strong, light color', "The sun is so bright today! There are no clouds in the sky.", '¿Qué lugar de Lima recuerdas especialmente bright, con mucha luz?', 'sight'],
    ['colorful', 'colorido, lleno de color (adj.)', 'having bright colors', 'On our walk we saw a beautiful field of colorful tulip flowers. They were bright red and yellow.', '¿Qué mercado o barrio te parece el más colorful?', 'sight'],
    ['damp', 'húmedo (adj.): ligeramente mojado, normalmente de forma desagradable', 'slightly wet, usually in an unpleasant way', 'Our socks were damp, so I put them on the radiator to dry.', '¿Tu casa se pone damp en el invierno limeño?', 'touch'],
    ['deep', 'grave, profundo (adj., de un sonido): de tono bajo', 'having a sound that is low', "People have always told me I have a nice deep voice, so I decided to try voice acting. I've recorded a few commercials.", '¿Tienes la voz deep o más bien aguda?', 'sound'],
    ['flavorful', 'sabroso, lleno de sabor (adj.)', 'having good flavor or a lot of flavor', 'We went to that new Indian restaurant for dinner. The food was so good and flavorful, full of so many different spices.', '¿Cuál es el plato más flavorful de tu negocio?', 'taste'],
    ['fresh', 'fresco (adj.): que huele a limpio o que se siente agradablemente fresco', 'smelling clean or feeling pleasantly cool', "It's nice to get out of the city and smell the fresh country air.", '¿Dónde respiras aire fresh cerca de Lima?', 'smell'],
    ['high-pitched', 'agudo (adj., de un sonido): más alto de lo normal', 'having a sound that is higher than usual', "I'm a voice actor. Because of my high-pitched voice, I often play the part of a teenager.", '¿Qué sonido high-pitched te molesta más?', 'sound'],
    ['melodic', 'melodioso (adj.): con un sonido musical muy agradable', 'having a very pleasant musical sound', 'I like when my roommate practices singing and playing guitar. She has such a nice, melodic voice.', '¿Qué cantante tiene la voz más melodic para ti?', 'sound'],
    ['musty', 'a humedad, a cerrado (adj.): que huele a viejo y ligeramente húmedo, de forma desagradable', 'smelling old and slightly wet in an unpleasant way', "The librarian showed us a room in the basement with lots of very old books. The room had a musty smell, but I didn't mind.", '¿Qué lugar recuerdas con olor musty?', 'smell'],
    ['rough', 'áspero, rugoso (adj.): con una superficie irregular, con agujeros o partes elevadas', 'having an irregular surface with holes or raised areas', 'We had to drive on a very rough road to get to the hike. The road was full of dirt and rocks.', '¿Qué camino rough has recorrido en el Perú?', 'touch'],
    ['scented', 'perfumado, aromático (adj.): con un olor agradable', 'having a pleasant smell', 'The spa provides a relaxing environment with scented candles that give the room a sweet smell.', '¿Usas velas scented en casa?', 'smell'],
    ['smooth', 'liso, suave (adj.): con una superficie regular, sin agujeros ni partes elevadas', 'having a regular surface with no holes or raised areas', "My father is a carpenter. When he gets wood, it's rough, so he uses sandpaper to make it smooth.", '¿Cómo consigues una masa smooth para las empanadas?', 'touch'],
    ['stinky', 'apestoso, maloliente (adj., informal)', 'having or producing an unpleasant smell', 'This soup is stinky. I need to throw it out.', '¿Qué comida stinky te gusta aunque huela mal?', 'smell'],
    ['tasty', 'rico, sabroso (adj.): comida con buen sabor y agradable de comer', 'food that has a good flavor and is nice to eat', 'I got some pizza on my way back to the hotel. It was so tasty! It tasted really fresh and flavorful.', '¿Qué es lo más tasty que has comido en Chile?', 'taste'],
  ];
  /* Lesson 2 · Describing memories */
  const ME = [
    ['bring back', 'traer (recuerdos), evocar (phr. v.): hacer que alguien piense en algo del pasado', 'to make someone think about something from the past', 'The smell of apples baking brings back memories of my mother making apple pie.', '¿Qué olor te brings back la infancia?'],
    ['childhood', 'infancia, niñez (n.): la parte de tu vida en que eres niño', 'the part of your life when you are a child', 'I spent a lot of my childhood with my cousins in Korea. They lived nearby, and we often played together in the park.', '¿Dónde pasaste tu childhood?'],
    ['clear', 'nítido, claro (adj., de un recuerdo): fácil de recordar', '(of a memory) easily remembered', 'I have a clear memory of going to the fair as a child and having my face painted. I remember that the paint felt strange on my face.', '¿Cuál es tu clear memory más antiguo?'],
    ['distant', 'lejano (adj., de un recuerdo): muy atrás en el pasado', 'far away in the past', "I have a distant memory of running through a field with my sister and brother. I don't remember a lot of the details. It was a long time ago.", '¿Tienes algún distant memory de antes de los cinco años?'],
    ['early', 'temprano, de la primera infancia (adj., de un recuerdo): de cuando eras muy pequeño', '(of a memory) from when you were a young child', "I have an early memory of walking with my mother in our old town in Japan. I must have been three or four years old.", '¿Cuál es tu early memory más claro?'],
    ['look back on', 'mirar atrás, recordar (phr. v.): pensar en algo que pasó en el pasado', 'to think about something that happened in the past', "I love looking at old photos. It's nice to look back on my past and remember when we were all so young.", '¿Qué etapa de tu vida te gusta look back on?'],
    ['long-term memory', 'memoria a largo plazo (n.): recordar información durante mucho tiempo', 'remembering information over a long period of time', 'Our long-term memory is not very reliable. My sister and I often remember the same events from our childhood differently.', '¿Confías en tu long-term memory? ¿Recuerdas igual que tus hermanos?'],
    ['recall', 'recordar, acordarse de (v.)', 'to remember something', "A: Do you remember when we were kids, we used to make capes from blankets and run around the front yard? B: Hmm, I don't recall that! How strange.", '¿Recall el nombre de tu primera profesora?'],
    ['recent', 'reciente (adj.): que pasó o empezó hace poco', 'happening or starting from a short time ago', 'Can you take a photo of me? I need a more recent photo for my profile. The one I have there is from five years ago.', '¿Cuál es tu recent memory favorito de este año?'],
    ['recognize', 'reconocer (v.): saber quién o qué es alguien o algo porque lo has visto o vivido antes', 'to know someone or something because you have seen or experienced them before', "A: It's Ronnie, from Chicago! B: Oh, Ronnie! Of course! I didn't recognize you after all these years. It's so good to see you!", '¿Alguna vez no recognize a un antiguo compañero?'],
    ['remind (someone) of', 'recordar a alguien algo, hacer pensar en (phr. v.): hacer que alguien piense en otra cosa o persona', 'to make someone think of something or someone else', 'This basketball court reminds me of my father. We used to come here all the time when I was a kid.', '¿Qué canción te reminds of la universidad?'],
    ['short-term memory', 'memoria a corto plazo (n.): recordar información durante poco tiempo', 'remembering information for a short time', "A: Oh, you already paid me $20. Here's your change. B: I did? Oh, dear. Thank you. My short-term memory isn't very good.", '¿Cómo anda tu short-term memory en la semana del release?'],
    ['vague', 'vago, borroso (adj.): no claro ni seguro', 'not clear or certain', 'I have only vague memories of my elementary school. I can remember some things about the building and some of my teachers.', '¿De qué época tienes recuerdos vague?'],
    ['vivid', 'vívido, muy nítido (adj., de un recuerdo): con una imagen fuerte y clara en la mente', '(of a memory) having a strong, clear image in your mind', "I have a vivid memory of feeding baby goats on my grandparents' farm as a child. I can remember the smell of the farm and the sound of the goats.", '¿Cuál es tu vivid memory más reciente?'],
  ];
  const ALL = [...SE, ...ME];
  const findW = k => ALL.find(x => x[0] === k);
  const SAY = { 'remind (someone) of': 'remind someone of', 'high-pitched': 'high pitched' };
  const SENSE_ES = { sight: 'Vista', sound: 'Oído', touch: 'Tacto', smell: 'Olfato', taste: 'Gusto' };

  /* situación → expresión: [frase con hueco, respuesta, clave en SE/ME, respuestas que NO sirven como distractor] */
  const SIT = [
    ["The sun on the beach in Máncora was so ___ that I couldn't open my eyes.", 'bright', 'bright', []],
    ["The market in Surquillo is full of fruit of every color. It's really ___.", 'colorful', 'colorful', ['bright']],
    ['It rained all night and the towels are still ___. Nothing dries in Lima in July.', 'damp', 'damp', []],
    ['My uncle has a ___ voice, like a radio announcer.', 'deep', 'deep', ['melodic']],
    ['The ají de gallina had so many spices. It was really ___.', 'flavorful', 'flavorful', ['tasty']],
    ['After the rain, the air in the park smelled clean and ___.', 'fresh', 'fresh', []],
    ['The smoke alarm makes a ___ sound that hurts my ears.', 'high-pitched', 'high-pitched', []],
    ['My grandmother used to sing while she cooked. Her voice was so ___.', 'melodic', 'melodic', ['deep']],
    ['The old storage room smelled ___, like wet books.', 'musty', 'musty', ['stinky', 'damp']],
    ['The road to the mountains was ___ and full of stones.', 'rough', 'rough', []],
    ['My wife lights ___ candles when she wants to relax. The whole house smells of vanilla.', 'scented', 'scented', ['fresh']],
    ['I worked the dough for ten minutes until it was ___.', 'smooth', 'smooth', []],
    ["Who left the fish in the fridge for a week? It's ___!", 'stinky', 'stinky', ['musty']],
    ['Your completos were so ___! Can I have another one?', 'tasty', 'tasty', ['flavorful']],
    ['The smell of fried onions always ___ memories of my first job in a kitchen.', 'brings back', 'bring back', ['reminds']],
    ['I spent my ___ between Lima and Santiago, so I have two accents.', 'childhood', 'childhood', []],
    ["I have a ___ memory of my first day at school: the blue uniform, the smell of new books, my teacher's voice.", 'clear', 'clear', ['vivid']],
    ['I have a ___ memory of a trip to Arequipa, but I was so young that I only remember the volcano.', 'distant', 'distant', ['early', 'vague']],
    ['My ___ memory is of my mother singing while she cooked. I must have been three.', 'early', 'early', ['distant']],
    ['When I ___ my university years, I only remember the good parts.', 'look back on', 'look back on', []],
    ["I still remember the phone number of my grandparents' house. My ___ is better than I thought.", 'long-term memory', 'long-term memory', ['short-term memory']],
    ["I don't ___ meeting him, but he says we worked together in 2015.", 'recall', 'recall', ['recognize']],
    ['This photo is from 2012. Do you have a more ___ one?', 'recent', 'recent', []],
    ["He had a beard and glasses, so I didn't ___ him at first.", 'recognize', 'recognize', ['recall']],
    ['That song always ___ me of my first car.', 'reminds', 'remind (someone) of', ['brings back']],
    ["I forgot what I came to the kitchen for. My ___ is terrible when I'm tired.", 'short-term memory', 'short-term memory', ['long-term memory']],
    ['I have only ___ memories of that year; I was working too much to notice anything.', 'vague', 'vague', ['distant']],
    ["I have a ___ memory of the earthquake of 2007: the noise, the dust, my mother's face.", 'vivid', 'vivid', ['clear']],
  ];
  const SITW = SIT.map(s => s[1]);

  window.UNIT_DATA['ingles4/unit12'] = {
    source: 'Evolve · Unit 12 · Senses and memories',
    description: 'Los sentidos y los recuerdos: adjetivos para lo que ves, oyes, tocas, hueles y saboreas; recuerdos <i>vivid, vague, distant</i>; dar énfasis con <i>What I love is… / The thing I like most is…</i>; evitar repeticiones con <i>one / ones / so</i> y referirse a ideas con <i>it, them, this, that</i>; y recordar y compartir experiencias en conversación (<i>That rings a bell / It\'s all coming back to me now / That reminds me of a story…</i>).',
    cando: [
      "Describir lugares, comidas y sonidos con los cinco sentidos: <i>bright, musty, smooth, high-pitched, flavorful…</i>",
      "Hablar de recuerdos con precisión: <i>a vivid / vague / distant / early memory</i>, <i>bring back, look back on, remind me of, recall, recognize</i>",
      "Dar énfasis a una idea con <i>What I love about… is…</i> y <i>The thing I like most is…</i>, con <i>be</i> bien concordado",
      "Evitar repetir con <i>one / ones</i>, el auxiliar (<i>If they did…</i>) y <i>so</i> (<i>I think so / If so…</i>), y referirme a ideas con <i>this / that</i>",
      "Provocar y compartir recuerdos: <i>Do you remember that time we…? · That rings a bell · It's all coming back to me now · I had a similar experience once…</i>",
    ],
    map: [
      ['Vocabulary', '14 adjetivos de los sentidos (<i>bright, colorful, damp, deep, flavorful, fresh, high-pitched, melodic, musty, rough, scented, smooth, stinky, tasty</i>) y 14 expresiones para describir recuerdos (<i>bring back, childhood, clear, distant, early, look back on, long-term memory, recall, recent, recognize, remind (someone) of, short-term memory, vague, vivid</i>)', 'Flashcards con audio, expresión ↔ definición, situación → expresión, ¿qué sentido?, colocaciones de memoria (<i>remember / recall / recognize / remind of</i>)'],
      ['Grammar', '<b>Adding emphasis</b>: <i>What I</i> + verbo / <i>The thing I</i> + verbo … + <i>be</i> + la idea que destacas; <i>be</i> concuerda (singular por defecto, plural con sustantivo plural). <b>Substitution and referencing</b>: <i>one / ones</i> por un sustantivo contable, el auxiliar por el verbo (<i>If they did…</i>), <i>so</i> por una cláusula (<i>I think so / If so…</i>); <i>it / them</i> para cosas concretas, <i>this / that</i> para ideas completas', 'Construye la frase enfática, <i>is</i> o <i>are</i>, elige <i>one / ones / so / did / them / this</i>, ¿a qué se refiere?, corrige errores típicos, ordena mini-diálogos, reescribe con énfasis y sin repetir, repaso Units 8-11'],
      ['Listening', 'Dos amigas que se reencuentran y recuerdan el colegio; una pareja que compara dos locales para el negocio', 'Dictado con voz sintética y dos diálogos nuevos con preguntas'],
      ['Speaking', 'Un recuerdo vívido con los cinco sentidos, lo que más te gusta de tu ciudad, mirar atrás al terminar el curso, comparar dos lugares sin repetir, compartir una experiencia parecida', 'Retos con cronómetro y reconocimiento de voz; entonación de las frases enfáticas y sílaba tónica de <i>MEmory, VIvid, REcognize, meLOdic</i>'],
      ['Reading', 'Por qué un olor te lleva treinta años atrás: el olfato y la memoria', 'Texto nuevo con vocabulario de los sentidos, frases enfáticas y sustitución + inferir significado'],
      ['Writing', 'Un recuerdo vívido contado con los sentidos; lo que más te gusta de un lugar', 'Corrige errores típicos (<i>remember of, this song remembers me, I hope it, the people is…</i>), describe con los sentidos, escribe tu recuerdo con checklist'],
      ['Social English', '<i>Don\'t tell me you don\'t remember · Do you remember that time we…? · I don\'t recall… · It\'s all coming back to me now · That rings a bell · That whole period\'s a bit vague · Has that ever happened to you? · I had a similar experience once… · That\'s like the time that… · That reminds me of a story…</i>', 'Ordenar diálogos, respuesta rápida, responder recordando, role-play con ramas: el reencuentro'],
    ],

    sections: [
      { id: 'home', label: 'Inicio', render: 'overview', activities: [] },

      /* ================= VOCABULARY ================= */
      { id: 'vocab', label: 'Vocabulary', activities: [
        { label: 'Flashcards', type: 'flashcards', eyebrow: 'Flashcards con audio', title: 'Toca la tarjeta para girarla', intro: 'Anverso: la palabra o expresión. Reverso: significado, ejemplo del curso y una pregunta para ti. Los adjetivos de los sentidos llevan su sentido en la etiqueta. Pulsa 🔊 para oír la pronunciación.',
          cards: [
            ...SE.map(t => ({ cat: 'Senses · ' + SENSE_ES[t[5]], w: t[0], def: t[1], ex: t[3], ask: t[4], say: SAY[t[0]] || t[0] })),
            ...ME.map(t => ({ cat: 'Describing memories', w: t[0], def: t[1], ex: t[3], ask: t[4], say: SAY[t[0]] || t[0] })),
          ] },
        { label: 'Senses ↔ Definición', type: 'match', eyebrow: 'Talking about the senses', title: 'Empareja el adjetivo con su definición', intro: 'Toca un adjetivo de la izquierda y luego su definición (en inglés, como en el curso) a la derecha. Pista: piensa primero con qué sentido va.',
          pairs: SE.map(t => [t[0], t[2]]), round: 6 },
        { label: 'Memories ↔ Definición', type: 'match', eyebrow: 'Describing memories', title: 'Empareja la expresión con su definición', intro: 'Las 14 expresiones para hablar de recuerdos. Ojo con los cuatro verbos que en español son "recordar": <i>recall, recognize, remind of, bring back</i>.',
          pairs: ME.map(t => [t[0], t[2]]), round: 6 },
        { label: '¿Qué expresión es?', type: 'mcq', eyebrow: 'En contexto', title: 'Lee la situación y elige la expresión', intro: 'Sentidos y recuerdos mezclados. Muchas situaciones salen de una cocina de fin de semana, de Lima y de Chile… ¿te suena?', pool: 8,
          build: ({ pick, esc }) => pick(SIT, 8).map(s => { const t = findW(s[2]); const bad = SITW.filter(x => x !== s[1] && !s[3].includes(x)); return { q: esc(s[0]).replace('___', '<span class="blank">?</span>'), opts: [s[1], ...pick(bad, 3)], a: s[1], why: `<b>${t[0]}</b> — ${t[1]}. “${t[3]}”` }; }) },
        { label: '¿Qué sentido?', type: 'mcq', eyebrow: 'Los cinco sentidos', title: '¿Con qué sentido percibes esto?', intro: 'Cada adjetivo de la unidad describe algo que ves (<i>sight</i>), oyes (<i>sound</i>), tocas (<i>touch</i>), hueles (<i>smell</i>) o saboreas (<i>taste</i>). Algunos valen para dos, pero en el curso cada uno tiene su sentido principal.', pool: 8, items: [
          { q: 'a melodic voice', opts: ['sound', 'sight', 'touch', 'smell'], a: 'sound', why: '<b>melodic</b> describe un sonido musical agradable → <i>sound</i>.' },
          { q: 'a musty basement', opts: ['smell', 'touch', 'taste', 'sight'], a: 'smell', why: '<b>musty</b> = olor a viejo y húmedo → <i>smell</i>.' },
          { q: 'a smooth surface', opts: ['touch', 'sight', 'sound', 'taste'], a: 'touch', why: '<b>smooth</b> (liso) se nota con las manos → <i>touch</i>.' },
          { q: 'a flavorful soup', opts: ['taste', 'smell', 'sight', 'touch'], a: 'taste', why: '<b>flavorful</b> = lleno de sabor → <i>taste</i>.' },
          { q: 'a bright morning', opts: ['sight', 'sound', 'smell', 'touch'], a: 'sight', why: '<b>bright</b> = lleno de luz → <i>sight</i>.' },
          { q: 'a high-pitched alarm', opts: ['sound', 'touch', 'taste', 'sight'], a: 'sound', why: '<b>high-pitched</b> = agudo, de tono alto → <i>sound</i>.' },
          { q: 'damp socks', opts: ['touch', 'smell', 'sight', 'sound'], a: 'touch', why: '<b>damp</b> = ligeramente mojado; lo sientes al tocar → <i>touch</i>.' },
          { q: 'scented candles', opts: ['smell', 'sight', 'taste', 'sound'], a: 'smell', why: '<b>scented</b> = perfumado → <i>smell</i>.' },
          { q: 'a colorful market', opts: ['sight', 'taste', 'smell', 'touch'], a: 'sight', why: '<b>colorful</b> = lleno de colores → <i>sight</i>.' },
          { q: 'a rough road', opts: ['touch', 'sound', 'sight', 'taste'], a: 'touch', why: '<b>rough</b> = áspero, irregular; se percibe por el tacto (o por las ruedas) → <i>touch</i>.' },
          { q: 'a deep voice', opts: ['sound', 'sight', 'touch', 'smell'], a: 'sound', why: '<b>deep</b>, hablando de voces, = grave → <i>sound</i>.' },
          { q: 'stinky cheese', opts: ['smell', 'sight', 'touch', 'sound'], a: 'smell', why: '<b>stinky</b> = apestoso → <i>smell</i>.' },
          { q: 'tasty empanadas', opts: ['taste', 'touch', 'sight', 'sound'], a: 'taste', why: '<b>tasty</b> = rico, sabroso → <i>taste</i>.' },
          { q: 'fresh mountain air', opts: ['smell', 'sight', 'sound', 'taste'], a: 'smell', why: 'En el curso, <b>fresh</b> = que huele a limpio o se siente fresco → <i>smell</i>.' },
        ] },
        { label: 'Recordar, de cuatro maneras', type: 'mcq', eyebrow: 'Colocaciones de memoria', title: 'remember · recall · recognize · remind of · bring back', intro: 'En español todo es "recordar"; en inglés no. <b>remember / recall</b> = acordarse de algo (sujeto: tú). <b>recognize</b> = reconocer (saber quién es). <b>remind someone of</b> = algo te hace pensar en otra cosa (sujeto: la cosa). <b>bring back memories</b> = evocar recuerdos. Y los adjetivos: <i>a vivid / clear / vague / distant / early / recent memory</i>.', pool: 8, items: [
          { blank: 1, q: 'This song ___ me of my first trip to Santiago.', opts: ['reminds', 'remembers', 'recalls', 'recognizes'], a: 'reminds', why: 'La canción te hace pensar en el viaje → <b>remind someone of</b>. <s>remembers me</s> es el calco número uno del español.' },
          { blank: 1, q: "I didn't ___ him with the beard. He looked like another person.", opts: ['recognize', 'remind', 'recall', 'bring back'], a: 'recognize', why: 'Saber quién es alguien al verlo → <b>recognize</b>.' },
          { blank: 1, q: "I don't ___ saying that, but maybe I did.", opts: ['recall', 'recognize', 'remind', 'look back'], a: 'recall', why: 'Acordarse de un hecho → <b>recall</b> (+ -ing). Sinónimo algo más formal de <i>remember</i>.' },
          { blank: 1, q: 'The smell of fresh bread ___ memories of my grandmother.', opts: ['brings back', 'remembers', 'recognizes', 'looks back on'], a: 'brings back', why: 'Un olor evoca recuerdos → <b>bring back memories</b>.' },
          { blank: 1, q: 'I have a ___ memory of the earthquake: I can still hear the noise and see the dust.', opts: ['vivid', 'vague', 'distant', 'recent'], a: 'vivid', why: 'Imagen fuerte y clara, con sonidos e imágenes → <b>vivid</b>.' },
          { blank: 1, q: 'I have only ___ memories of my first school. I remember the building, not the people.', opts: ['vague', 'vivid', 'clear', 'recent'], a: 'vague', why: 'Recuerdos poco claros → <b>vague</b>.' },
          { blank: 1, q: 'My ___ memory is of my father carrying me on his shoulders. I was two or three.', opts: ['earliest', 'most recent', 'short-term', 'vaguest'], a: 'earliest', why: 'De cuando eras muy pequeño → <b>early</b> (superlativo <i>earliest</i>).' },
          { blank: 1, q: 'I can remember a song from 1998, but not what I had for lunch. My ___ is the problem.', opts: ['short-term memory', 'long-term memory', 'childhood', 'early memory'], a: 'short-term memory', why: 'Lo reciente se te olvida → falla la <b>short-term memory</b>.' },
          { blank: 1, q: 'When I ___ my twenties, I see a very different person.', opts: ['look back on', 'bring back', 'remind of', 'recognize'], a: 'look back on', why: 'Pensar en una etapa pasada → <b>look back on</b>.' },
          { blank: 1, q: "This is a ___ photo, from last month. The other one is ten years old.", opts: ['recent', 'distant', 'early', 'vague'], a: 'recent', why: 'De hace poco → <b>recent</b>.' },
          { blank: 1, q: 'You look familiar. Do I ___ you from the university?', opts: ['know', 'remind', 'recall', 'bring back'], a: 'know', why: 'Para preguntar si conoces a alguien: <b>Do I know you?</b> (<i>remember</i> también vale). <i>Remind</i> necesita objeto + <i>of</i>.' },
          { blank: 1, q: 'That old kitchen ___ me of my first job: the heat, the noise, the smell of oil.', opts: ['reminds', 'recalls', 'remembers', 'recognizes'], a: 'reminds', why: 'El sujeto es la cocina y el objeto eres tú → <b>reminds me of</b>.' },
          { blank: 1, q: 'I have a very ___ memory of that night; I can tell you every detail.', opts: ['clear', 'vague', 'distant', 'short-term'], a: 'clear', why: 'Lo recuerdas con todo detalle → <b>clear</b>.' },
          { blank: 1, q: 'I spent my ___ in a small town in the south of Chile.', opts: ['childhood', 'early memory', 'long-term memory', 'recall'], a: 'childhood', why: 'La etapa en que eres niño → <b>childhood</b>.' },
        ] },
      ] },

      /* ================= GRAMMAR ================= */
      { id: 'grammar', label: 'Grammar', activities: [
        { label: 'Notas', type: 'notes', eyebrow: 'Adding emphasis · Substitution and referencing', title: 'Destacar una idea y no repetirte', html: `
          <h3>1 · Adding emphasis: "What I love is…"</h3>
          <p style="margin:8px 0 14px">Para dar <b>énfasis</b> a una idea, empiezas con <b>What I</b> + verbo o <b>The thing I</b> + verbo, y pones la idea que quieres destacar <b>al final</b>, después de <b>be</b>. Es el equivalente de "Lo que me encanta es…" / "Lo que más me gusta es…".</p>
          <div class="scroll-x"><table class="table"><thead><tr><th>Parte 1 (lo que destacas)</th><th>be</th><th>Parte 2 (la idea)</th><th>Pista</th></tr></thead><tbody>
            <tr><td><b>What I love</b></td><td><b>is</b></td><td>the peace and quiet.</td><td>Frase del curso. Sujeto + verbo dentro de <i>What…</i>; nada de <s>What I love it is</s>.</td></tr>
            <tr><td><b>The thing I like most</b></td><td><b>is</b></td><td>being so close to nature.</td><td>Después de <i>be</i> puede ir un sustantivo, un <b>-ing</b> o una cláusula con <i>that</i>.</td></tr>
            <tr><td><b>What I noticed first</b></td><td><b>was</b></td><td>the friendliness of the people.</td><td><i>be</i> va en el tiempo de la historia: <i>noticed</i> → <b>was</b>.</td></tr>
            <tr><td><b>What I didn't know</b></td><td><b>is</b></td><td>that the town is such a cultural place.</td><td>Negativa dentro de la primera parte: <i>didn't know</i>, <i>don't like</i>.</td></tr>
            <tr><td><b>What I love about this place</b></td><td><b>are</b></td><td>all the sports you can do.</td><td><i>be</i> concuerda con la idea destacada: <b>singular por defecto</b>, pero <b>plural</b> si lo que sigue es un sustantivo plural.</td></tr>
            <tr><td><b>The thing I really appreciate</b></td><td><b>is</b></td><td>the ease of travel from here to anywhere!</td><td>Puedes añadir <i>that</i>: <i>The thing <b>that</b> I appreciate…</i>; nunca <s>The thing what</s>.</td></tr>
          </tbody></table></div>
          <div class="hint" style="margin-top:14px"><b>Trampas del hispanohablante:</b> "Lo que" se traduce <b>What</b>, no <s>That</s> ni <s>Which</s>: <i><b>What</b> I love is the food</i>. · "La cosa que" → <b>The thing (that)</b>: <s>the thing what</s>. · No repitas el objeto: <s>What I like <b>it</b> is</s>. · Concordancia: <i>What I like <b>is</b> the food</i> (singular) · <i>What I like <b>are</b> the colors</i> (plural). · Puedes destacar también con <i>What matters is… / What surprised me was…</i></div>
          <h3 style="margin-top:22px">2 · Substitution: one / ones · auxiliar · so</h3>
          <p style="margin:8px 0 14px">En inglés se evita repetir. Hay tres sustitutos según lo que no quieres repetir.</p>
          <div class="scroll-x"><table class="table"><thead><tr><th>No repitas…</th><th>Usa…</th><th>Ejemplo del curso</th><th>Pista</th></tr></thead><tbody>
            <tr><td>un <b>sustantivo contable</b></td><td><b>one</b> (singular) / <b>ones</b> (plural)</td><td>They were all wearing masks like <b>the ones</b> worn by skiers.<br>Three of the men drove away. <b>The one</b> left behind took off his mask.</td><td>Concuerda en número: <i>the red <b>one</b></i> (one bag), <i>the red <b>ones</b></i> (those bags). Con incontables no: <s>some fresh one</s> → <i>some fresh bread</i>.</td></tr>
            <tr><td>un <b>verbo o frase verbal</b></td><td>el <b>auxiliar</b> del tiempo: <i>do / does / did / have / was / can / will…</i></td><td>The police hope that someone saw these men. If they <b>did</b>, they should contact the police.</td><td><i>saw</i> → pasado → <b>did</b>. <i>Have you been there? Yes, I <b>have</b>.</i></td></tr>
            <tr><td>una <b>cláusula entera</b> tras una pregunta</td><td><b>so</b> (y <b>not</b> para la negativa)</td><td>Did you see anything that might help? If <b>so</b>, call the hotline.</td><td><i>I think <b>so</b> / I hope <b>so</b> / I guess <b>so</b> / I'm afraid <b>not</b> / I hope <b>not</b></i>. Nunca <s>I think that yes</s>, <s>I hope it</s>.</td></tr>
          </tbody></table></div>
          <h3 style="margin-top:22px">3 · Referencing: it / them · this / that</h3>
          <div class="scroll-x"><table class="table"><thead><tr><th>Para referirte a…</th><th>Usa…</th><th>Ejemplo del curso</th></tr></thead><tbody>
            <tr><td>un <b>sustantivo o frase nominal</b> concreta</td><td><b>it</b> (singular) / <b>them</b> (plural)</td><td>These two pieces of art were stolen. The museum is anxious to get <b>them</b> back.</td></tr>
            <tr><td>una <b>idea completa</b> (varias frases, una situación)</td><td><b>this</b> / <b>that</b></td><td>The men carried the two pieces to a white van, then drove away. <b>All this</b> happened at night.</td></tr>
          </tbody></table></div>
          <div class="hint small" style="margin-top:12px"><b>one vs it:</b> <i>I lost my umbrella, so I bought <b>one</b></i> (otro cualquiera) · <i>I lost my umbrella, but I found <b>it</b></i> (el mismo). <b>this vs that:</b> <i>this</i> apunta a lo que acabas de decir o vas a decir; <i>that</i>, a lo que dijo la otra persona o a algo ya cerrado: <i>"We stayed up all night." "<b>That</b> sounds exhausting."</i> · <b>people</b> es plural: <i>the people <b>are</b> friendly</i>, nunca <s>the people is</s>.</div>` },
        { label: 'Frases enfáticas', type: 'mcq', eyebrow: 'Adding emphasis', title: 'Construye la frase enfática', intro: 'Elige la palabra que completa la estructura: <b>What I</b> / <b>The thing (that) I</b> + verbo + <b>be</b> + la idea. Recuerda: "lo que" = <i>What</i>, y después de <i>the thing</i> va <i>that</i> o nada.', pool: 8, items: [
          { blank: 1, q: '___ I love about this neighborhood is the smell of fresh bread in the morning.', opts: ['What', 'That', 'Which', 'Who'], a: 'What', why: '"Lo que me encanta" → <b>What I love</b>. <s>That I love</s> no existe como inicio enfático.' },
          { blank: 1, q: 'The thing I like most about the new kitchen ___ the light.', opts: ['is', 'are', 'be', 'it is'], a: 'is', why: 'La idea destacada es singular (<i>the light</i>) → <b>is</b>. Y sin <i>it</i>: la primera parte ya es el sujeto.' },
          { blank: 1, q: 'What I noticed first ___ the friendliness of the people.', opts: ['was', 'were', 'is being', 'did'], a: 'was', why: 'Frase del curso: <i>noticed</i> es pasado → <b>was</b>; la idea es singular.' },
          { blank: 1, q: 'What I love about this place ___ all the sports you can do.', opts: ['are', 'is being', 'be', 'does'], a: 'are', why: 'Frase del curso: con un sustantivo plural (<i>all the sports</i>) puedes usar <b>are</b>.' },
          { blank: 1, q: 'The thing I really appreciate ___ being so close to my family.', opts: ['is', 'are', 'were', 'it is'], a: 'is', why: 'Después de <i>be</i> puede ir un <b>-ing</b>; <i>being</i> es singular → <b>is</b>.' },
          { blank: 1, q: "What I ___ know is that the town is such a cultural place.", opts: ["didn't", "don't knew", 'not', "wasn't"], a: "didn't", why: 'Frase del curso: la negativa va dentro de la primera parte: <b>What I didn\'t know</b>.' },
          { blank: 1, q: '___ I remember most about my childhood is the sound of the rain on the roof.', opts: ['What', 'The thing what', 'Which', 'That'], a: 'What', why: '<b>What I remember most</b>. <s>The thing what</s> es un error típico.' },
          { blank: 1, q: "The thing ___ I miss most is my grandmother's cooking.", opts: ['that', 'what', 'which', 'who'], a: 'that', why: 'Después de <i>the thing</i>: <b>that</b> (o nada). Nunca <i>what</i>.' },
          { blank: 1, q: 'What I love ___ this city is the food.', opts: ['about', 'of', 'from', 'in'], a: 'about', why: '<b>What I love about</b> + lugar / persona / cosa. Como <i>What do you like <b>about</b> it?</i>' },
          { blank: 1, q: "What we didn't expect ___ the price.", opts: ['was', 'were', 'is', 'did'], a: 'was', why: 'Historia en pasado (<i>didn\'t expect</i>) e idea singular → <b>was</b>.' },
          { blank: 1, q: 'The things I liked most about the course ___ the role-plays and the dictations.', opts: ['were', 'was', 'is', 'be'], a: 'were', why: 'Sujeto plural (<i>the things</i>) e ideas plurales → <b>were</b>.' },
          { blank: 1, q: 'What I ___ is the peace and quiet.', opts: ['love', 'loves', 'am love', 'loving'], a: 'love', why: 'Frase del curso: <i>I love</i>, presente simple. <i>Peace and quiet</i> se trata como una sola idea → <i>is</i>.' },
          { blank: 1, q: 'What surprised me ___ how small the campus was.', opts: ['was', 'were', 'is', 'has'], a: 'was', why: 'También puedes destacar con <b>What surprised me was…</b>: pasado y cláusula (<i>how small…</i>) → <i>was</i>.' },
          { blank: 1, q: '___ matters is that you tried.', opts: ['What', 'That', 'It', 'Which'], a: 'What', why: '<b>What matters is…</b> = lo que importa es…' },
          { blank: 1, q: "What I like about the market ___ the colors and the noise.", opts: ['are', 'is being', 'be', 'does'], a: 'are', why: 'Dos cosas (<i>the colors and the noise</i>) → plural → <b>are</b>.' },
          { blank: 1, q: "The thing I ___ about Lima is the traffic.", opts: ["don't like", "not like", "doesn't like", 'no like'], a: "don't like", why: 'Negativa dentro de la primera parte con <i>I</i>: <b>don\'t like</b>.' },
        ] },
        { label: 'is o are', type: 'mcq', eyebrow: 'Concordancia de be', title: '¿Singular o plural?', intro: 'En la frase enfática, <i>be</i> concuerda con la idea que destacas: <b>singular</b> por defecto (un sustantivo singular, un <i>-ing</i>, una cláusula con <i>that</i>), <b>plural</b> si lo que sigue es un sustantivo plural. Y el tiempo (<i>is / was</i>) sigue al de la historia.', pool: 8, items: [
          { blank: 1, q: 'What I love about my job ___ the people.', opts: ['are', 'is'], a: 'are', why: '<i>the people</i> es plural en inglés → <b>are</b>.' },
          { blank: 1, q: 'What I love about my job ___ working with people.', opts: ['is', 'are'], a: 'is', why: 'Un <b>-ing</b> cuenta como singular → <i>is</i>.' },
          { blank: 1, q: 'The thing I remember most ___ the scented candles on the table.', opts: ['is', 'are'], a: 'is', why: 'El sujeto es <i>the thing</i> (singular); con <i>The thing…</i> se usa normalmente <b>is</b>, aunque la idea sea plural.' },
          { blank: 1, q: 'What I noticed first ___ the bright colors of the houses.', opts: ['were', 'was'], a: 'were', why: 'Pasado + sustantivo plural (<i>the bright colors</i>) → <b>were</b>. (<i>was</i> también se oye en conversación.)' },
          { blank: 1, q: 'What I hated ___ that the room smelled musty.', opts: ['was', 'were'], a: 'was', why: 'Cláusula con <i>that</i> = singular, y pasado → <b>was</b>.' },
          { blank: 1, q: 'What I like about the restaurant ___ the tasty food.', opts: ['is', 'are'], a: 'is', why: '<i>food</i> es incontable → singular → <b>is</b>.' },
          { blank: 1, q: 'What brings back my childhood ___ the smell of wet earth.', opts: ['is', 'are'], a: 'is', why: 'Un sustantivo singular (<i>the smell</i>) → <b>is</b>.' },
          { blank: 1, q: 'What I miss ___ my friends from school.', opts: ['are', 'is'], a: 'are', why: 'Plural (<i>my friends</i>) → <b>are</b>.' },
          { blank: 1, q: "What I didn't expect ___ how deep his voice was.", opts: ['was', 'were'], a: 'was', why: 'Pasado + cláusula (<i>how deep…</i>) → <b>was</b>.' },
          { blank: 1, q: 'The thing we appreciate most ___ the fresh air.', opts: ['is', 'are'], a: 'is', why: 'Singular en los dos lados → <b>is</b>.' },
        ] },
        { label: 'one, ones, so…', type: 'mcq', eyebrow: 'Substitution and referencing', title: 'Elige el sustituto', intro: '¿Qué no quieres repetir? Un <b>sustantivo contable</b> → <i>one / ones</i>. Un <b>verbo</b> → el auxiliar (<i>did, have, can…</i>). Una <b>cláusula</b> tras una pregunta → <i>so / not</i>. Una <b>cosa concreta</b> → <i>it / them</i>. Una <b>idea completa</b> → <i>this / that</i>.', pool: 8, items: [
          { blank: 1, q: "I don't like these candles. Do you have any scented ___?", opts: ['ones', 'one', 'them', 'so'], a: 'ones', why: 'Sustituye a <i>candles</i> (plural) → <b>ones</b>.' },
          { blank: 1, q: 'Which empanada do you want, the spicy one or the sweet ___?', opts: ['one', 'ones', 'it', 'so'], a: 'one', why: 'Una empanada → <b>one</b>.' },
          { blank: 1, q: 'Is the bakery still open? I think ___.', opts: ['so', 'it', 'that', 'yes'], a: 'so', why: '<b>I think so</b> sustituye a toda la cláusula (<i>that it is still open</i>).' },
          { blank: 1, q: 'Did you see the photos? If ___, send them to me.', opts: ['so', 'yes', 'it', 'them'], a: 'so', why: '<b>If so</b> = si es así. Frase del curso: <i>If so, call the hotline</i>.' },
          { blank: 1, q: 'Did anyone recognize the man? If they ___, they should call the police.', opts: ['did', 'recognized', 'do', 'were'], a: 'did', why: 'El verbo (<i>recognized</i>, pasado) se sustituye por su auxiliar: <b>did</b>.' },
          { blank: 1, q: 'These two paintings were stolen. The museum wants ___ back.', opts: ['them', 'it', 'ones', 'so'], a: 'them', why: 'Cosas concretas en plural → <b>them</b>. Frase del curso.' },
          { blank: 1, q: 'He lost his keys, his phone and his wallet in one morning. All ___ happened before nine.', opts: ['this', 'it', 'them', 'one'], a: 'this', why: 'Se refiere a toda la situación → <b>all this</b>.' },
          { blank: 1, q: 'Will it rain tomorrow? I hope ___.', opts: ['not', 'no', 'it not', 'so not'], a: 'not', why: 'Negativa de <i>I hope so</i> → <b>I hope not</b>.' },
          { blank: 1, q: 'I love old photos, especially the ___ from my childhood.', opts: ['ones', 'one', 'them', 'it'], a: 'ones', why: '<i>photos</i> plural → <b>the ones</b>.' },
          { blank: 1, q: "Is Renato coming to the reunion? I don't think ___.", opts: ['so', 'it', 'that', 'him'], a: 'so', why: '<b>I don\'t think so</b>. Nunca <s>I don\'t think it</s>.' },
          { blank: 1, q: 'My short-term memory is bad, but my long-term ___ is excellent.', opts: ['one', 'ones', 'it', 'so'], a: 'one', why: 'Sustituye a <i>memory</i> (singular contable aquí) → <b>one</b>.' },
          { blank: 1, q: "You say the room smelled musty. ___ is true, but I didn't mind.", opts: ['That', 'It', 'One', 'So'], a: 'That', why: 'Te refieres a lo que dijo la otra persona (una idea) → <b>That</b>.' },
          { blank: 1, q: 'Have you been to the new café? Yes, I ___, last week.', opts: ['have', 'did', 'was', 'so'], a: 'have', why: 'Pregunta en present perfect → respuesta con el mismo auxiliar: <b>I have</b>.' },
          { blank: 1, q: "I can't find my glasses. Have you seen ___?", opts: ['them', 'it', 'ones', 'so'], a: 'them', why: '<i>glasses</i> es plural → <b>them</b>.' },
          { blank: 1, q: "Can you remember his name? If you ___, write it down.", opts: ['can', 'do', 'did', 'so'], a: 'can', why: 'El verbo es <i>can remember</i> → se sustituye por el modal: <b>can</b>.' },
          { blank: 1, q: 'I lost my umbrella yesterday, so I bought ___ this morning.', opts: ['one', 'it', 'them', 'so'], a: 'one', why: 'Otro paraguas cualquiera → <b>one</b>. <i>It</i> sería el mismo paraguas.' },
        ] },
        { label: '¿A qué se refiere?', type: 'mcq', eyebrow: 'Referencing', title: 'Lee y di a qué sustituye la palabra', intro: 'Pequeños textos con un sustituto en mayúsculas. Decide a qué se refiere. Es la misma habilidad que usas al leer rápido en inglés.', items: [
          { q: 'My sister and I remember the same events differently. I remember us flying kites on the beach; she thinks we only flew THEM in the park. → THEM =', opts: ['the kites', 'the events', 'my sister and I'], a: 'the kites', why: '<i>flew them</i> = <i>flew the kites</i>. <b>them</b> sustituye al sustantivo plural concreto.' },
          { q: 'Three men ran out of the museum with two paintings. ONE dropped his mask. → ONE =', opts: ['one of the men', 'one of the paintings', 'one museum'], a: 'one of the men', why: 'Solo las personas pueden dejar caer una máscara: <b>one</b> = uno de los hombres.' },
          { q: "I didn't recognize my old teacher, and I called her by the wrong name. THAT was embarrassing. → THAT =", opts: ['the whole situation', 'the teacher', 'the name'], a: 'the whole situation', why: '<b>that</b> apunta a toda la idea anterior, no a un sustantivo.' },
          { q: 'Did you keep your school notebooks? If you DID, bring them to the reunion. → DID =', opts: ['kept your school notebooks', 'brought them', 'went to the reunion'], a: 'kept your school notebooks', why: 'El auxiliar sustituye al verbo anterior en pasado: <i>If you kept them</i>.' },
          { q: 'Will the smell of paint go away by Monday? I hope SO. → SO =', opts: ['that it goes away by Monday', 'the smell', 'Monday'], a: 'that it goes away by Monday', why: '<b>so</b> sustituye a la cláusula completa.' },
          { q: 'We stayed up all night, lost the project at 5 a.m. and rewrote it in three hours. ALL THIS happened the day before the exam. → ALL THIS =', opts: ['everything that happened that night', 'the project', 'the exam'], a: 'everything that happened that night', why: '<b>this</b> resume varias acciones = una idea completa.' },
          { q: "I liked the colorful cups, not the white ONES. → ONES =", opts: ['cups', 'colors', 'the colorful cups'], a: 'cups', why: '<b>ones</b> = <i>cups</i>; el adjetivo cambia (<i>white</i>), el sustantivo no se repite.' },
          { q: 'My grandmother kept a box of letters in the basement. Years later I found IT, damp and musty. → IT =', opts: ['the box', 'the basement', 'my grandmother'], a: 'the box', why: 'La cosa concreta que encuentras y que está húmeda: <b>it</b> = the box.' },
        ] },
        { label: 'Corrige las frases', type: 'fix', eyebrow: 'Error correction · errores típicos de la unidad', title: 'Reescribe la frase corrigiendo el error', intro: 'Los errores más frecuentes del hispanohablante con el énfasis y la sustitución. Corrígelos y compara con la solución.', items: [
          { bad: 'What I like it is the smell of fresh bread.', good: 'What I like is the smell of fresh bread.', why: 'No repitas el objeto: <i>What I like</i> ya es el sujeto de la frase. <s>What I like it is</s>.' },
          { bad: 'The thing that I like most are the food.', good: 'The thing that I like most is the food.', why: '<i>food</i> es incontable (singular) y el sujeto es <i>the thing</i> → <b>is</b>.' },
          { bad: 'That I love about Lima is the food.', good: 'What I love about Lima is the food.', why: '"Lo que" = <b>What</b>, no <i>that</i>.' },
          { bad: "I don't want these shoes; I want the black one.", good: "I don't want these shoes; I want the black ones.", why: '<i>shoes</i> es plural → <b>ones</b>.' },
          { bad: 'Is she coming? I think that so.', good: 'Is she coming? I think so.', why: '<b>I think so</b>, sin <i>that</i>. (Y <i>I think that yes</i> tampoco existe.)' },
          { bad: 'Will the smell go away? I hope it.', good: 'Will the smell go away? I hope so.', why: 'Para sustituir una cláusula tras una pregunta: <b>I hope so / I hope not</b>, nunca <s>I hope it</s>.' },
          { bad: 'The people in that town is very friendly.', good: 'The people in that town are very friendly.', why: '<b>people</b> es plural en inglés → <i>are</i>.' },
          { bad: 'What I noticed first were the smell of the sea.', good: 'What I noticed first was the smell of the sea.', why: 'La idea destacada es singular (<i>the smell</i>) → <b>was</b>.' },
          { bad: 'Do you have a more recent photo? This ones is from 2012.', good: 'Do you have a more recent photo? This one is from 2012.', why: 'Una foto → <b>this one</b>. <i>Ones</i> solo con plural (<i>these ones</i>).' },
          { bad: 'The thing what I remember most is the music.', good: 'The thing that I remember most is the music.', why: 'Después de <i>the thing</i> va <b>that</b> (o nada: <i>The thing I remember most</i>), nunca <i>what</i>.' },
          { bad: 'Did you call your mother? If yes, tell her hi.', good: 'Did you call your mother? If so, tell her hi.', why: '"Si es así" → <b>If so</b>. <i>If yes</i> es un calco.' },
          { bad: 'These paintings are very old. The museum wants to protect it.', good: 'These paintings are very old. The museum wants to protect them.', why: '<i>paintings</i> plural → <b>them</b>.' },
          { bad: "What I didn't knew is that the town is so old.", good: "What I didn't know is that the town is so old.", why: 'Después de <i>didn\'t</i>, verbo base: <b>didn\'t know</b>.' },
        ] },
        { label: 'Ordena el mini-diálogo', type: 'order', eyebrow: 'Énfasis y sustitución en conversación', title: 'Toca las líneas en el orden correcto', dialogs: [
          ['Ana: So, how was the trip to Valparaíso?', 'Luis: Amazing. What I loved most was the colorful houses on the hills.', 'Ana: And the food? Was it as good as people say?', "Luis: Better. The thing I didn't expect was how fresh the fish was.", 'Ana: Did you take photos?', "Luis: Hundreds. I'll show you the best ones tonight."],
          ['Paula: Do you still have the notebooks from our first year?', "Marco: I think so. They're in a box in the basement.", "Paula: Isn't it damp down there?", "Marco: It is. If the notebooks are still there, they probably smell musty.", 'Paula: Can you check? If so, bring them to the reunion.', 'Marco: Sure. What I remember most about them is your terrible drawings.'],
          ['Diego: Which candle should I buy, the vanilla one or the lemon one?', 'Rosa: The vanilla one. The lemon ones smell like cleaning products.', "Diego: Really? I didn't notice that.", 'Rosa: What I like about vanilla is that it reminds me of my grandmother.', 'Diego: Did she bake a lot?', 'Rosa: Every Sunday. The smell of her kitchen brings back my whole childhood.'],
        ] },
        { label: 'Dale énfasis', type: 'soft', eyebrow: 'Adding emphasis · escritura', title: 'Reescribe la frase destacando la idea', explain: 'Lee la frase normal y reescríbela con énfasis: <b>What I</b> + verbo + <b>is / are / was</b> + la idea, o <b>The thing I</b> + verbo + <b>is</b> + la idea. Pon la idea al final y cuida la concordancia (<i>is</i> con singular y <i>-ing</i>, <i>are</i> con plural, <i>was</i> en pasado).', missing: 'Falta la estructura enfática: empieza con <i>What I… / The thing I…</i> y conecta con <i>is / are / was / were</i>', pattern: /^(?:what|the thing(?: that)?) (?:i|we|he|she|they|you|my \w+|surprised|matters|strikes)\b.*\b(?:is|are|was|were)\b/, items: [
          { h: 'I love the smell of the sea. (What I…)', a: 'What I love is the smell of the sea.' },
          { h: 'I like the colorful market in Surquillo most. (The thing I…)', a: 'The thing I like most is the colorful market in Surquillo.' },
          { h: 'I noticed the fresh air first. (What I…, en pasado)', a: 'What I noticed first was the fresh air.' },
          { h: "I didn't know that the town was so old. (What I…)", a: "What I didn't know was that the town was so old." },
          { h: "I miss my grandmother's cooking most. (The thing I…)", a: "The thing I miss most is my grandmother's cooking." },
          { h: "I remember the deep voice of my grandfather. (What I…)", a: 'What I remember is the deep voice of my grandfather.' },
          { h: 'We appreciate the scented candles and the soft music. (What we…, plural)', a: 'What we appreciate are the scented candles and the soft music.' },
          { h: "I love all the colors of Lima's markets. (What I love about Lima…, plural)", a: 'What I love about Lima are all the colors of its markets.' },
        ] },
        { label: 'No te repitas', type: 'soft', eyebrow: 'Substitution and referencing · escritura', title: 'Reescribe la segunda parte sin repetir', explain: 'Cada frase repite algo que un nativo no repetiría. Reescríbela usando <b>one / ones</b> (sustantivo contable), el <b>auxiliar</b> (<i>If you did…</i>), <b>so</b> (<i>I think so / If so…</i>), <b>it / them</b> (cosa concreta) o <b>this / that</b> (idea completa).', missing: 'Falta el sustituto: <i>one / ones · if so · I think so · If you did… · want them · all this…</i>', pattern: /\b(?:\w+ ones?\b|if so\b|i (?:think|hope|guess|suppose|believe|don['’]t think) so\b|if (?:you|they|we|he|she|i|it) (?:did|do|does|were|was|have|has|had|can|could|will|would)\b|(?:get|want|wants|wanted|bring|brought|send|sent|take|took|found|find|see|saw|lost|love|loved|remember|recall|recognize|recognized|gave|give|protect) (?:them|it)\b|all (?:this|that)\b)/, items: [
          { h: 'I bought a red notebook and a blue notebook.', a: 'I bought a red notebook and a blue one.' },
          { h: 'These empanadas are tastier than the empanadas we made last week.', a: 'These empanadas are tastier than the ones we made last week.' },
          { h: 'Did you see the photo? If you saw the photo, send it to me.', a: 'Did you see the photo? If you did, send it to me.' },
          { h: 'Do you remember her name? If you remember her name, tell me.', a: 'Do you remember her name? If so, tell me.' },
          { h: 'Is the restaurant still open? I think the restaurant is still open.', a: 'Is the restaurant still open? I think so.' },
          { h: 'Which cake do you want, the chocolate cake or the lemon cake?', a: 'Which cake do you want, the chocolate one or the lemon one?' },
          { h: 'The two paintings were stolen. The museum wants the two paintings back.', a: 'The two paintings were stolen. The museum wants them back.' },
          { h: 'He forgot his keys, lost his phone and missed the bus. Forgetting his keys, losing his phone and missing the bus happened before 9 a.m.', a: 'He forgot his keys, lost his phone and missed the bus. All this happened before 9 a.m.' },
        ] },
        { label: 'Repaso Units 8-11', type: 'mcq', eyebrow: 'Repaso espaciado', title: 'Units 8-11 con vocabulario de la Unit 12', intro: 'Segundo condicional y <i>wish</i> (Unit 8), permiso y prohibición (Unit 9), tercer condicional y modales de probabilidad pasada (Unit 10), <i>forget / remember / stop</i> + -ing o infinitivo y causativos (Unit 11). Última vuelta del ciclo.', items: [
          { blank: 1, q: 'If I ___ more time, I would look back on my old photos more often.', opts: ['had', 'would have', 'have', 'will have'], a: 'had', why: 'Segundo condicional: <i>if</i> + <b>pasado simple</b> (Unit 8).' },
          { blank: 1, q: "I can't remember the smell of my grandmother's kitchen. I wish I ___ it.", opts: ['could remember', 'can remember', 'remembered', 'would remember'], a: 'could remember', why: '<i>can\'t</i> → <b>wish + could</b> (Unit 8).' },
          { blank: 1, q: "Visitors ___ touch the paintings. It's forbidden.", opts: ["aren't allowed to", "don't have to", "aren't supposed", 'may'], a: "aren't allowed to", why: 'Prohibición en presente: <b>not be allowed to</b> + verbo (Unit 9).' },
          { blank: 1, q: 'In my school we ___ wear a uniform every single day.', opts: ['had to', 'must', 'were allowed', 'could'], a: 'had to', why: 'Obligación en el pasado: <b>had to</b> (Unit 9).' },
          { blank: 1, q: 'If I had kept a diary, I ___ more of my childhood.', opts: ['would remember', 'will remember', 'would have remember', 'remembered'], a: 'would remember', why: 'Condición pasada con resultado presente: <i>if</i> + past perfect → <b>would</b> + verbo. (Con resultado pasado sería <i>would have remembered</i>; Unit 10.)' },
          { blank: 1, q: "He didn't recognize me. He ___ forgotten my face completely.", opts: ['must have', 'should have', "can't have", 'might'], a: 'must have', why: 'Deducción segura sobre el pasado: <b>must have</b> + participio (Unit 10).' },
          { blank: 1, q: "I'll never forget ___ the sea for the first time. I was five.", opts: ['seeing', 'to see', 'see', 'saw'], a: 'seeing', why: 'Recuerdo de algo que pasó → <b>forget + -ing</b> (Unit 11).' },
          { blank: 1, q: 'The smell of musty books always ___ me sneeze.', opts: ['makes', 'lets', 'helps to', 'does'], a: 'makes', why: 'Causativo <b>make</b> + objeto + verbo base: provoca el estornudo (Unit 11).' },
        ] },
      ] },

      /* ================= LISTENING ================= */
      { id: 'listen', label: 'Listening', activities: [
        { label: 'Dictado', type: 'dictation', eyebrow: 'Dictation', title: 'Escucha y escribe exactamente lo que oyes', intro: 'Usa la voz del navegador. Repite las veces que quieras y baja la velocidad si hace falta. Ojo con las frases enfáticas (<i>What I… is…</i>), con <i>the ones</i> y con las contracciones (<i>that\'s, it\'s, period\'s</i>).',
          sentences: ['What I love about this place is the peace and quiet.', 'The thing I like most is being so close to nature.', 'What I noticed first was the friendliness of the people.', 'They were all wearing masks like the ones worn by skiers.', 'Did you see anything that might help? If so, call the hotline.', 'The museum is anxious to get them back.', "I have a vivid memory of feeding baby goats on my grandparents' farm.", 'The smell of apples baking brings back memories of my mother.', "I didn't recognize you after all these years.", 'Do you remember that time we got lost in Santiago?', "That rings a bell, but that whole period's a bit vague.", "It's all coming back to me now.", 'I had a similar experience once.'] },
        { label: 'Diálogo 1 · El reencuentro', type: 'dialog', eyebrow: 'Listening for memories', title: 'Dos amigas del colegio se encuentran en una boda', intro: 'Lucía y Paola no se ven desde el colegio. Escucha cómo se reconocen, qué recuerdan bien y qué recuerdan a medias.',
          lines: [['Paola', "Lucía? Lucía Ramos? Don't tell me you don't remember me!"], ['Lucía', "Paola! Of course! Sorry, I didn't recognize you with the short hair. It's been, what, fifteen years?"], ['Paola', "At least. Do you remember that time we hid in the chemistry lab during the fire drill?"], ['Lucía', "Hmm… that rings a bell, but that whole period's a bit vague. Wait – the lab with the musty smell and the broken window?"], ['Paola', "That's the one! And Miss Torres found us because you were laughing so loudly."], ['Lucía', "Oh no. It's all coming back to me now. She had that high-pitched voice… I can still hear her saying our names."], ['Paola', "What I remember most is the smell of that lab. Old chemicals and damp books."], ['Lucía', "Funny, isn't it? I can't recall what I had for lunch yesterday, but I remember that smell perfectly."], ['Paola', "That's like the time I walked into my old school in Trujillo. The smell of the floor wax brought back my whole childhood in one second."], ['Lucía', "Has that ever happened to you with music? For me it's any song from 2005."]],
          questions: [
            { q: "Why didn't Lucía recognize Paola at first?", opts: ['Because Paola has short hair now', 'Because Paola has a high-pitched voice', 'Because Lucía was laughing'], a: 'Because Paola has short hair now', why: '"I didn\'t recognize you with the short hair."' },
            { q: 'How well does Lucía remember the fire drill at first?', opts: ['Only vaguely; it rings a bell', 'Perfectly, with every detail', 'Not at all; she denies it'], a: 'Only vaguely; it rings a bell', why: '"That rings a bell, but that whole period\'s a bit vague." Después, con los detalles, "it\'s all coming back to me now".' },
            { q: 'What does Paola remember most about the lab?', opts: ['Its smell', 'Its bright windows', "Miss Torres's voice"], a: 'Its smell', why: '"What I remember most is the smell of that lab." Frase enfática.' },
            { q: 'What brought back Paola\'s childhood in Trujillo?', opts: ['The smell of the floor wax', 'A song from 2005', 'A photo of her school'], a: 'The smell of the floor wax', why: '"The smell of the floor wax brought back my whole childhood in one second."' },
            { q: 'What does "That\'s the one!" mean here?', opts: ["Yes, that's exactly the lab I mean", 'That is the only lab in the school', 'That lab was number one'], a: "Yes, that's exactly the lab I mean", why: '<b>the one</b> sustituye a <i>the lab</i>: "ese es, exactamente".' },
          ] },
        { label: 'Diálogo 2 · Dos locales', type: 'dialog', eyebrow: 'Listening for emphasis and substitution', title: 'Aldo y Dani comparan dos locales para el negocio', intro: 'La pareja ha visto dos locales para abrir por fin una tienda de La Consentida. Escucha qué destaca cada uno y qué deciden.',
          lines: [['Dani', "OK, be honest. Which one did you like, the one on the corner or the one near the park?"], ['Aldo', "The one near the park. What I loved was the light – that big bright window in the morning."], ['Dani', "I liked that one too. But the kitchen is tiny. The thing I liked most about the other one was the kitchen."], ['Aldo', "True. But did you notice the smell? The whole place was damp and musty."], ['Dani', "I did. That's what worried me. If the walls are wet, that could be a serious problem."], ['Aldo', "Exactly. And the one near the park smelled fresh, like someone had just painted it."], ['Dani', "So, the park one? Even with the small kitchen?"], ['Aldo', "I think so. We can fix a small kitchen. We can't fix a musty building."], ['Dani', "You're right. What matters is that the customers feel comfortable. All this – the light, the smell – is what they notice first."], ['Aldo', "Then it's decided. I'll call the owner tomorrow. If she's still interested, we sign on Friday."]],
          questions: [
            { q: 'What did Aldo love about the place near the park?', opts: ['The light from the big window', 'The size of the kitchen', 'The price'], a: 'The light from the big window', why: '"What I loved was the light – that big bright window in the morning."' },
            { q: 'What was the main advantage of the place on the corner?', opts: ['The kitchen', 'The smell', 'The window'], a: 'The kitchen', why: '"The thing I liked most about the other one was the kitchen."' },
            { q: 'Why do they reject the place on the corner?', opts: ['It smelled damp and musty, so the walls may be wet', 'It had no kitchen', 'The owner was not interested'], a: 'It smelled damp and musty, so the walls may be wet', why: '"The whole place was damp and musty." … "If the walls are wet, that could be a serious problem."' },
            { q: 'What does "I think so" replace?', opts: ['that we should take the park one', 'the small kitchen', 'the owner'], a: 'that we should take the park one', why: '<b>so</b> sustituye a toda la cláusula de la pregunta anterior.' },
            { q: 'According to Dani, what do customers notice first?', opts: ['The light and the smell', 'The size of the kitchen', 'The price of the empanadas'], a: 'The light and the smell', why: '"All this – the light, the smell – is what they notice first."' },
          ] },
      ] },

      /* ================= SPEAKING ================= */
      { id: 'speak', label: 'Speaking', activities: [
        { label: 'Retos', type: 'speaking', eyebrow: 'Speaking challenge', challenges: [
          { t: 'A vivid memory, with all five senses', task: 'Cuenta un recuerdo vívido de tu infancia usando los cinco sentidos: qué veías, oías, tocabas, olías y saboreabas. Usa al menos cinco adjetivos de la unidad y dos expresiones de memoria (vivid, bring back, remind me of, recall…).', model: "I have a vivid memory of my grandmother's kitchen in Santiago. I must have been six or seven. What I remember first is the smell: fresh bread and something sweet, maybe quince. The kitchen was small and bright, with a colorful tablecloth that was always a bit damp because she cleaned it every five minutes. I can still hear her deep voice singing old boleros, and the high-pitched whistle of the kettle. I remember touching the dough – rough at first, then smooth – and the taste of the first empanada, hot and flavorful. Even now, when I fry onions on a Saturday for La Consentida, the smell brings back that kitchen. It reminds me of her, and honestly, that's why I started the business.", tags: ['vivid memory', 'smell', 'fresh', 'bright', 'colorful', 'damp', 'deep', 'high-pitched', 'rough', 'smooth', 'flavorful', 'brings back', 'reminds me of'] },
          { t: 'What I love about my city', task: 'Describe lo que más te gusta (y lo que menos) de Lima o de tu barrio, con al menos cuatro frases enfáticas: What I love about… is… / The thing I like most is… / What I don\'t like is… / What surprised me was… Cuida la concordancia de be.', model: "People complain about Lima all the time, but what I love about this city is the food. The thing I like most is that you can eat something amazing for ten soles on any corner. What I also love are the colors of the markets: the fruit, the flowers, the noise. What I don't like, obviously, is the traffic. The thing that really annoys me is spending two hours a day in a bus. And the weather in winter: what nobody tells you is that the damp gets into your bones. What surprised me when I came back from Chile was how much I had missed the smell of the sea in Barranco. What matters, in the end, is that this is home.", tags: ['what i love about', 'the thing i like most is', "what i don't like is", 'what surprised me was', 'what matters is', 'colors', 'damp', 'smell'] },
          { t: 'Looking back on this course', task: 'Es la última unidad del ciclo. Mira atrás: ¿qué recuerdas con claridad, qué es vago, qué te ha servido más? Usa look back on, a clear / vague memory, What I remember most is…, The thing that helped me most was…, y algún I wish o If I had… de Units 8 y 10.', model: "When I look back on this course, I have a clear memory of the first unit: the present perfect, the introductions, and how nervous I was speaking in front of the class. Some units are a bit vague now – I think the one about advertising? – but what I remember most is the role-plays. The thing that helped me most was practicing out loud every day, even for ten minutes. If I had done that from the beginning, I'd be more fluent now. I wish I had recorded myself more often, too. What I'm proud of is that I can now explain a technical problem in English without panicking. And what I'll take with me are the phrases: 'That rings a bell', 'If I were in your shoes'… I use them at work every week.", tags: ['look back on', 'clear memory', 'vague', 'what i remember most is', 'the thing that helped me most was', 'if i had', 'i wish i had', "what i'm proud of"] },
          { t: 'Two places, no repetition', task: 'Compara dos lugares (dos restaurantes, dos playas, dos locales, dos barrios) durante un minuto sin repetir sustantivos: usa the one / the ones, so, it / them, this / that. Termina diciendo cuál eliges y por qué con una frase enfática.', model: "There are two cevicherías near my office. The one on the corner is cheap and always full; the one near the park is quieter but more expensive. The food? The dishes at the corner one are bigger, but the ones at the park place are fresher. Is the fish good at both? I think so, but the park one has a stinky kitchen smell on hot days, and I don't love that. The service is friendly at both, but the people at the corner one remember your name, and that matters to me. So, which one do I choose? The corner one. What I love about it is the noise, the colorful walls, and the fact that everyone is there: bankers, students, taxi drivers. All this makes it feel like Lima.", tags: ['the one', 'the ones', 'i think so', 'that', 'all this', 'what i love about it is', 'stinky', 'fresher', 'colorful'] },
          { t: 'That reminds me of a story…', task: 'Un amigo te cuenta que perdió un día entero de trabajo por no guardar un archivo. Responde compartiendo una experiencia parecida con las frases de la unidad: Has that ever happened to you? / I had a similar experience once… / That\'s like the time that… / That reminds me of a story… Cuenta la anécdota en pasado y cierra con una frase enfática.', model: "Oh no, a whole day? That reminds me of a story. I had a similar experience once, at the bank, about two years ago. It was a Friday – of course it was a Friday – and I was deploying a change to production. What I didn't know was that the backup had failed the night before. The deployment broke a table, and when I went to restore it, there was nothing to restore. I have a vivid memory of my manager's face: completely white. We rewrote the data by hand from logs until two in the morning. That's like the time at university when we lost the whole project an hour before the deadline. Has that ever happened to you with a thesis? Anyway, what I learned is simple: never trust a backup you haven't tested.", tags: ['that reminds me of a story', 'i had a similar experience once', "that's like the time", 'has that ever happened to you', "what i didn't know was", 'vivid memory', 'what i learned is'] },
        ] },
        { label: 'Pronunciación', type: 'stress', eyebrow: 'Pronunciación · entonación enfática y sílaba tónica', title: '"What I LOVE is…" y MEmory / VIvid / REcognize', intro: 'En la frase enfática, el verbo de la primera parte lleva el golpe de voz y hay una pequeña pausa antes de <i>is</i>: <i>What I LOVE … is the food</i>. Después, las frases de la conversación con sus contracciones, y la sílaba fuerte (en MAYÚSCULAS) del vocabulario. Escucha y repite.',
          pairs: [['What I LOVE is… (pausa antes de is)', 'What I love is the peace and quiet.'], ['The THING I like MOST is…', 'The thing I like most is being close to nature.'], ['What I NOticed first was…', 'What I noticed first was the friendliness of the people.'], ["What I DIDN'T know is…", "What I didn't know is that the town is so old."], ['the ONES → "thi-wúnz"', 'They were wearing masks like the ones worn by skiers.'], ['I think so · I hope so · I hope not', 'I think so. I hope so. I hope not.'], ['If so → "if-SO"', 'If so, call the hotline.'], ["Don't tell me you don't remember!", "Don't tell me you don't remember!"], ['That rings a BELL', 'That rings a bell.'], ["It's all coming BACK to me now", "It's all coming back to me now."], ["That whole period's a bit VAGUE", "That whole period's a bit vague."], ['MEmory · MEmories', 'memory, memories'], ['VIvid · VAGUE ("veig") · DIStant', 'vivid, vague, distant'], ['REcognize · reCALL · reMIND', 'recognize, recall, remind'], ['CHILDhood · LONG-term · SHORT-term', 'childhood, long-term memory, short-term memory'], ['meLOdic · high-PITCHED · FLAvorful', 'melodic, high-pitched, flavorful'], ['MUSty · SCENted · DAMP · SMOOTH · ROUGH ("raf")', 'musty, scented, damp, smooth, rough'], ['Frase completa', "What I remember most about my childhood is the smell of fresh bread, and that's the one thing that always brings it back."]] },
      ] },

      /* ================= READING ================= */
      { id: 'read', label: 'Reading', activities: [
        { type: 'reading', eyebrow: 'Reading for main ideas · inferring meaning', title: 'Why a smell can take you back thirty years', intro: 'Lee una vez para la idea general y otra fijándote en los adjetivos de los sentidos, en las frases enfáticas y en los sustitutos (<i>the ones, so, this</i>). Las palabras en amarillo se preguntan después: intenta deducirlas por el contexto.',
          paragraphs: [
            "You walk past a bakery, catch a <b>whiff</b> of warm bread, and suddenly you are six years old again, sitting in your grandmother's kitchen. You didn't decide to remember; the memory simply arrived, vivid and complete. Scientists call this the Proust effect, after the French writer who described a whole childhood returning with the taste of a small cake. What is strange is that a photo of the same kitchen would probably not produce the same feeling.",
            "The reason is anatomy. Information from your eyes and ears travels through several stations before it reaches the parts of the brain that store memories. Smell doesn't. The nerves that detect odors connect almost directly to the amygdala and the hippocampus, the areas that handle emotion and long-term memory. In other words, the link between smell and memory is <b>hardwired</b>: it is built into the brain, not learned. This is also why the memories that smells bring back are so emotional. You don't just recall the kitchen; you feel it.",
            "There is a second difference. Visual memories <b>fade</b> quickly, because we see thousands of images a day and the brain replaces the old ones with the new ones. Smells are rarer. You may not smell your school's floor wax or your father's aftershave again for twenty years, so the memory stays untouched, like a letter in a sealed box. The first time the smell returns, it opens the box, and the memory is as clear as the day it was stored.",
            "Can you use this? Researchers think so. Students who studied with a scented candle and then smelled the same scent during the exam remembered more. Some therapists use familiar smells to help older people with vague memories recall their past. And the thing you can do at home is simple: the next time something smells musty, fresh, or stinky, stop for a second and notice what it <b>triggers</b>. What you find may surprise you.",
          ],
          main: [
            { q: 'A smell can bring back a complete memory without you trying.', opts: ['1', '2', '3', '4'], a: '1', why: 'Párrafo 1: <i>You didn\'t decide to remember; the memory simply arrived, vivid and complete</i>.' },
            { q: 'Smell reaches the memory areas of the brain more directly than sight or hearing.', opts: ['1', '2', '3', '4'], a: '2', why: 'Párrafo 2: <i>The nerves that detect odors connect almost directly to the amygdala and the hippocampus</i>.' },
            { q: 'Memories connected to smells stay clear because we meet those smells rarely.', opts: ['1', '2', '3', '4'], a: '3', why: 'Párrafo 3: <i>Smells are rarer… so the memory stays untouched</i>.' },
            { q: 'The smell-memory link can be used for studying and for therapy.', opts: ['1', '2', '3', '4'], a: '4', why: 'Párrafo 4: estudiantes con velas perfumadas y terapeutas con personas mayores.' },
          ],
          infer: [
            { q: '<b>whiff</b> (paragraph 1)', opts: ['a brief smell of something', 'a loud noise', 'a slice of bread'], a: 'a brief smell of something', why: '<i>catch a whiff of warm bread</i>: lo que percibes al pasar junto a la panadería es un olor breve.' },
            { q: '<b>hardwired</b> (paragraph 2)', opts: ['built into the brain, not learned', 'connected with cables', 'very difficult'], a: 'built into the brain, not learned', why: 'El texto lo explica justo después: <i>it is built into the brain, not learned</i>.' },
            { q: '<b>fade</b> (paragraph 3)', opts: ['become weaker and disappear slowly', 'become brighter', 'repeat many times'], a: 'become weaker and disappear slowly', why: 'Las imágenes se reemplazan y se pierden; se contrasta con las memorias de olores, que <i>stay untouched</i>.' },
            { q: '<b>triggers</b> (paragraph 4)', opts: ['causes or starts', 'destroys', 'smells like'], a: 'causes or starts', why: 'Qué provoca o despierta el olor: un recuerdo, una emoción.' },
          ],
          think: '¿Qué olor te devuelve a tu infancia? ¿Y cuál te recuerda tu primer trabajo? Escribe tres frases: una con <i>What I remember most about… is…</i>, una con <i>bring back</i> o <i>remind me of</i> y una con un sustituto (<i>the one / the ones / so / that</i>).' },
      ] },

      /* ================= WRITING ================= */
      { id: 'write', label: 'Writing', activities: [
        { label: 'Contar un recuerdo', type: 'notes', eyebrow: 'Writing skill · describing a memory', title: 'Cómo se estructura un recuerdo bien contado', html: `<div class="grid2" style="margin-top:12px">
          <div><h3>A · Estructura</h3><ul class="small" style="padding-left:18px;margin:6px 0"><li><b>Presenta el recuerdo:</b> I have a vivid / clear / early memory of… / When I look back on my childhood, …</li><li><b>Sitúalo:</b> I must have been six or seven. / It was a Sunday in winter. / We were living in…</li><li><b>Los sentidos, uno a uno:</b> What I remember first is the smell of… / I can still hear… / The floor was rough and damp… / It tasted…</li><li><b>Qué lo trae de vuelta hoy:</b> Even now, the smell of… brings back that kitchen. / That song reminds me of…</li><li><b>Por qué importa (énfasis):</b> What matters is… / The thing I miss most is… / What I didn't know then was…</li></ul></div>
          <div><h3>B · Frases útiles</h3><ul class="small" style="padding-left:18px;margin:6px 0"><li><i>I can't recall every detail, but…</i></li><li><i>That whole period is a bit vague, except for one afternoon.</i></li><li><i>It's a distant memory, but a happy one.</i> (<b>one</b> = memory)</li><li><i>My sister remembers it differently. If she's right, …</i></li><li><i>I don't think so, but my long-term memory isn't reliable.</i></li><li><i>All this happened more than twenty years ago.</i></li></ul></div>
          <div class="hint small"><b>Ojo:</b> <i>remember / recall</i> + <b>-ing</b> para el pasado: <i>I remember feeding the goats</i>. · <i>remind</i> necesita objeto: <i>It reminds <b>me</b> of…</i>; <s>it remembers me</s>. · <i>a memory <b>of</b> something</i>, no <s>a memory about</s>. · <i>childhood</i> sin artículo cuando es "la infancia" en general: <i>in my childhood</i>, <i>during childhood</i>. · <i>smell <b>of</b> bread</i> (el olor a pan), <i>smell <b>like</b> bread</i> (oler a pan). · Los adjetivos no tienen plural: <s>vagues memories</s> → <i>vague memories</i>.</div></div>` },
        { label: 'Corrige las frases', type: 'fix', eyebrow: 'Error correction · recuerdos y sentidos', title: 'Reescribe la frase corrigiendo el error', intro: 'Errores típicos al contar recuerdos y describir con los sentidos. Un solo error por frase.', items: [
          { bad: 'I remember of my first day at school very well.', good: 'I remember my first day at school very well.', why: '<b>remember</b> lleva objeto directo, sin <i>of</i>. (El <i>of</i> va con <i>remind me <b>of</b></i>.)' },
          { bad: 'This song remembers me my father.', good: 'This song reminds me of my father.', why: 'La canción te hace pensar en él → <b>remind someone of</b>. <i>Remember</i> no puede tener una canción como sujeto.' },
          { bad: 'I have a very vivid memory about the earthquake.', good: 'I have a very vivid memory of the earthquake.', why: '<b>a memory of</b> something.' },
          { bad: 'My memories of that year are very vagues.', good: 'My memories of that year are very vague.', why: 'Los adjetivos en inglés no tienen plural: <b>vague</b>.' },
          { bad: 'The smell of fresh bread bring back my childhood.', good: 'The smell of fresh bread brings back my childhood.', why: 'El sujeto es <i>the smell</i> (singular) → <b>brings</b>.' },
          { bad: "I don't recall to see him at the party.", good: "I don't recall seeing him at the party.", why: '<b>recall / remember + -ing</b> para algo del pasado.' },
          { bad: 'The kitchen smelled to onions and coffee.', good: 'The kitchen smelled of onions and coffee.', why: 'Olía a… → <b>smelled of</b> (o <i>smelled like</i>). <s>smelled to</s> es un calco de "olía a".' },
          { bad: 'Her voice was very high-pitch and strong.', good: 'Her voice was very high-pitched and strong.', why: 'El adjetivo es <b>high-pitched</b>, con <i>-ed</i>.' },
          { bad: 'I have a early memory of the beach in Chile.', good: 'I have an early memory of the beach in Chile.', why: '<i>early</i> empieza por vocal → <b>an</b>.' },
          { bad: 'When I look back my school years, I feel happy.', good: 'When I look back on my school years, I feel happy.', why: 'El phrasal verb es <b>look back on</b> + algo.' },
          { bad: "I didn't recognized my cousin at the airport.", good: "I didn't recognize my cousin at the airport.", why: 'Después de <i>didn\'t</i>, verbo base: <b>recognize</b>.' },
          { bad: 'The road was very rough and the car made a sound very high-pitched.', good: 'The road was very rough and the car made a very high-pitched sound.', why: 'El adjetivo va <b>antes</b> del sustantivo: <i>a very high-pitched sound</i>.' },
        ] },
        { label: 'Describe con los sentidos', type: 'soft', eyebrow: 'Talking about the senses · escritura', title: 'Convierte la frase plana en una descripción', explain: 'Cada frase dice algo general ("the soup was good"). Reescríbela con uno o dos adjetivos de los sentidos de la unidad: <b>bright, colorful, damp, deep, flavorful, fresh, high-pitched, melodic, musty, rough, scented, smooth, stinky, tasty</b>. Puedes añadir detalle.', missing: 'Falta un adjetivo de los sentidos de la unidad: <i>bright, colorful, damp, deep, flavorful, fresh, high-pitched, melodic, musty, rough, scented, smooth, stinky, tasty</i>', pattern: /\b(?:bright|colorful|damp|deep|flavorful|fresh|high-pitched|melodic|musty|rough|scented|smooth|stinky|tasty)\b/, items: [
          { h: 'The soup was good. (gusto)', a: 'The soup was tasty and flavorful, with a lot of ají.' },
          { h: 'The basement smelled bad. (olfato, viejo y húmedo)', a: 'The basement smelled musty, like old wet books.' },
          { h: 'The market had many colors. (vista)', a: 'The market was bright and colorful, full of fruit and flowers.' },
          { h: 'The singer had a nice low voice. (oído)', a: 'The singer had a deep, melodic voice.' },
          { h: 'The towels were a little wet. (tacto)', a: 'The towels were still damp in the morning.' },
          { h: 'The alarm made a horrible noise. (oído)', a: 'The alarm made a horrible high-pitched sound.' },
          { h: 'The air in the mountains was nice. (olfato)', a: 'The air in the mountains was fresh and clean.' },
          { h: 'The old table was not smooth. (tacto)', a: 'The old table was rough, and the new one is smooth.' },
          { h: 'The room smelled nice because of the candles. (olfato)', a: 'The room smelled sweet because of the scented candles.' },
          { h: 'The fish in the fridge smelled terrible. (olfato, informal)', a: 'The fish in the fridge was stinky; we had to throw it out.' },
        ] },
        { label: 'Escribe tu recuerdo', type: 'comment', eyebrow: 'Writing task', title: 'Un recuerdo vívido', intro: 'Escribe 100-150 palabras sobre un recuerdo vívido (de la infancia, de un viaje, de tu primer trabajo). Preséntalo (<i>I have a vivid memory of…</i>), sitúalo en el tiempo, descríbelo con al menos tres sentidos, di qué lo trae de vuelta hoy y cierra con una frase enfática. La checklist se marca sola al analizar el texto.', placeholder: "I have a vivid memory of… I must have been… What I remember first is the smell of… I can still hear… Even now, … brings back… What matters is…", min: 100, max: 150, need: 5, checks: [
          { label: 'Presento el recuerdo con vocabulario de la unidad (<i>vivid / clear / early / distant memory, look back on, childhood</i>)', re: /\b(?:vivid|clear|early|earliest|distant|vague|recent) memor(?:y|ies)\b|\blook(?:ing|ed)? back on\b|\bchildhood\b/ },
          { label: 'Uso al menos tres adjetivos de los sentidos (<i>bright, colorful, damp, deep, flavorful, fresh, high-pitched, melodic, musty, rough, scented, smooth, stinky, tasty</i>)', re: /\b(bright|colorful|damp|deep|flavorful|fresh|high-pitched|melodic|musty|rough|scented|smooth|stinky|tasty)\b[\s\S]*\b(bright|colorful|damp|deep|flavorful|fresh|high-pitched|melodic|musty|rough|scented|smooth|stinky|tasty)\b[\s\S]*\b(bright|colorful|damp|deep|flavorful|fresh|high-pitched|melodic|musty|rough|scented|smooth|stinky|tasty)\b/ },
          { label: 'Digo qué lo trae de vuelta: <i>brings back / reminds me of / recall / recognize</i>', re: /\b(?:brings? back|brought back|reminds? me of|reminded me of|recall|recognized?)\b/ },
          { label: 'Uso una frase enfática (<i>What I remember most is… / The thing I miss most is… / What matters is…</i>)', re: /\b(?:what|the thing(?: that)?) (?:i|we|my \w+|matters|surprised|strikes)\b[^.?!]*\b(?:is|are|was|were)\b/ },
          { label: 'Evito repetir con un sustituto (<i>the one / the ones / so / that / all this</i>)', re: /\b(?:the (?:\w+ )?ones?|a happy one|if so|i think so|i hope so|i don['’]t think so|all (?:this|that)|that(?:['’]s| is| was) (?:why|what|when))\b/ },
          { label: 'Sitúo el recuerdo en el tiempo (<i>I must have been… / It was a… / years ago / when I was…</i>)', re: /\b(?:i must have been|it was a|years ago|when i was|at the time|back then|every (?:sunday|saturday|summer|winter|morning))\b/ },
          { label: 'Narro en pasado (<i>was / were / -ed / used to / could</i>)', re: /\b(?:was|were|used to|could|had|\w+ed)\b/ },
        ] },
        { label: 'Lo que más me gusta', type: 'comment', eyebrow: 'Writing task · short', title: 'Lo que más (y menos) te gusta de un lugar', intro: 'Escribe 40-80 palabras sobre un lugar (tu barrio, tu cocina, tu oficina, una playa) con tres frases enfáticas: una con <b>What I love about… is…</b>, una con <b>The thing I like most is…</b> y una negativa (<b>What I don\'t like is…</b>). Añade un adjetivo de los sentidos y un porqué.', placeholder: "What I love about my neighborhood is… The thing I like most is… What I don't like is… because…", min: 40, max: 80, need: 4, checks: [
          { label: '<i>What I love / like about… is / are…</i>', re: /\bwhat i (?:love|like|enjoy|appreciate)(?: most| the most)?(?: about [^.?!]*?)? (?:is|are)\b/ },
          { label: '<i>The thing I like most is…</i>', re: /\bthe thing(?: that)? i [^.?!]*?\b(?:is|are|was)\b/ },
          { label: 'Una enfática negativa: <i>What I don\'t like / hate / miss is…</i>', re: /\bwhat i (?:don['’]t like|don['’]t love|hate|miss|can['’]t stand|didn['’]t expect|didn['’]t know) [^.?!]*?\b(?:is|are|was|were)\b/ },
          { label: 'Un adjetivo de los sentidos', re: /\b(?:bright|colorful|damp|deep|flavorful|fresh|high-pitched|melodic|musty|rough|scented|smooth|stinky|tasty)\b/ },
          { label: 'Explico el porqué con <i>because</i>', re: /\bbecause\b/ },
        ] },
      ] },

      /* ================= SOCIAL ENGLISH ================= */
      { id: 'social', label: 'Social English', activities: [
        { label: 'Frases', type: 'notes', eyebrow: 'Functional language · Lesson 3', title: 'Recordar juntos y compartir experiencias', html: `<div class="grid2" style="margin-top:12px">
          <div><h3>Prompting a response</h3><ul class="small" style="padding-left:18px;margin:6px 0"><li><b>Don't tell me you don't remember!</b></li><li><b>Do you remember that time we</b> got lost in Santiago?</li><li><b>Remember when</b> we hid in the lab? (informal)</li></ul></div>
          <div><h3>Recalling a memory</h3><ul class="small" style="padding-left:18px;margin:6px 0"><li><b>I don't recall</b> that. / <b>I don't recall</b> seeing him.</li><li><b>That rings a bell.</b> (me suena)</li><li><b>It's all coming back to me now.</b> (ya me acuerdo)</li><li><b>That whole period's a bit vague.</b> (esa época la tengo borrosa)</li></ul></div>
          <div><h3>Sharing experiences</h3><ul class="small" style="padding-left:18px;margin:6px 0"><li><b>Has that ever happened to you?</b></li><li><b>I had a similar experience once…</b></li><li><b>That's like the time that</b> I lost my passport.</li><li><b>That reminds me of a story…</b></li></ul></div>
          <div><h3>Responding</h3><ul class="small" style="padding-left:18px;margin:6px 0"><li><b>How could I forget?</b></li><li><b>Of course I remember!</b></li><li><b>Was that the time…?</b></li><li><b>Honestly, it's a blur.</b> (todo borroso)</li></ul></div>
          <div class="hint small"><b>Cómo suena natural:</b> <i>That rings a bell</i> es tibio: te suena, pero no estás seguro; detrás viene una pregunta (<i>Was that the summer we…?</i>). <i>It's all coming back to me now</i> se dice cuando los detalles de la otra persona te activan el recuerdo. <i>That whole period's a bit vague</i> = <i>That whole period <b>is</b> a bit vague</i>: la <i>'s</i> es <i>is</i>, no posesivo. <br><b>Para compartir:</b> primero reaccionas (<i>Oh no / Really? / Ha!</i>), después enganchas con <b>That reminds me of a story</b> o <b>I had a similar experience once</b>, cuentas en pasado y devuelves el turno con <b>Has that ever happened to you?</b> Así la conversación es un ping-pong, no dos monólogos. <br><b>Ojo:</b> <i>Do you remember that time <b>we</b>…</i> (sujeto + pasado, sin <i>when</i> después de <i>that time</i>); <i>remind me <b>of</b></i>, no <s>remind me</s> a secas ni <s>remember me</s>.</div></div>` },
        { label: 'Ordena el diálogo', type: 'order', eyebrow: 'Ordena el diálogo', title: 'Toca las líneas en el orden correcto', dialogs: [
          ["Sofía: Tomás! Don't tell me you don't remember me!", "Tomás: Sofía? From the chemistry lab? Of course! I didn't recognize you with the glasses.", 'Sofía: Do you remember that time we set off the fire alarm?', "Tomás: Hmm… that rings a bell. Was that the day of the exam?", 'Sofía: Yes! And Miss Torres made us clean the lab for a week.', "Tomás: Oh, it's all coming back to me now. The smell of that cleaning liquid!"],
          ["Nico: Last week I lost a whole day of work because I forgot to save a file.", 'Bea: Oh no. Has that ever happened to you before?', 'Nico: Once, at university. But this time it was a client report.', 'Bea: That reminds me of a story. I had a similar experience once with a thesis chapter.', 'Nico: Did you get it back?', "Bea: No. I rewrote it from memory, and honestly, the second one was better."],
          ["Carla: Remember when we used to buy bread at that bakery on the corner?", "Hugo: Honestly, that whole period's a bit vague. Which bakery?", 'Carla: The one with the blue door. The whole street smelled of fresh bread at seven.', "Hugo: The blue door… yes! It's all coming back to me now. The owner had a really deep voice.", "Carla: That's the one. It closed years ago, but the smell still brings it back for me.", "Hugo: That's like the time I walked past my old school. One whiff of floor wax and I was ten again."],
        ] },
        { label: 'Respuesta rápida', type: 'mcq', eyebrow: 'Respuesta rápida', title: '¿Qué dices?', items: [
          { q: 'Ves a un antiguo compañero y parece que no te reconoce. Le provocas.', opts: ["Don't tell me you don't remember me!", 'I had a similar experience once.', 'That rings a bell.'], a: "Don't tell me you don't remember me!", why: '<b>Don\'t tell me you don\'t remember!</b> es la frase para provocar la respuesta.' },
          { q: 'Quieres que tu amigo recuerde una anécdota concreta.', opts: ['Do you remember that time we got lost in Santiago?', 'Do you remember that time when we got lost in Santiago?', 'Do you remind that time we got lost in Santiago?'], a: 'Do you remember that time we got lost in Santiago?', why: '<b>Do you remember that time we…?</b> Sin <i>when</i> después de <i>that time</i>, y <i>remember</i>, no <i>remind</i>.' },
          { q: 'Te suena lo que cuentan, pero no estás seguro.', opts: ['That rings a bell.', "It's all coming back to me now.", 'How could I forget?'], a: 'That rings a bell.', why: '<b>That rings a bell</b> = me suena. Las otras dos indican que ya lo recuerdas bien.' },
          { q: 'Con los detalles que te dan, de repente recuerdas todo.', opts: ["It's all coming back to me now.", "That whole period's a bit vague.", "I don't recall that."], a: "It's all coming back to me now.", why: '<b>It\'s all coming back to me now</b> = ya me acuerdo de todo.' },
          { q: 'De esa época no recuerdas casi nada.', opts: ["That whole period's a bit vague.", 'That rings a bell.', "That's like the time that…"], a: "That whole period's a bit vague.", why: '<b>That whole period\'s a bit vague</b> = esa época la tengo borrosa.' },
          { q: 'Niegas educadamente recordar algo.', opts: ["I don't recall that, sorry.", "I don't remind that, sorry.", "I don't recognize that time, sorry."], a: "I don't recall that, sorry.", why: '<b>I don\'t recall</b> + objeto / -ing. <i>Remind</i> y <i>recognize</i> significan otra cosa.' },
          { q: 'Tu amigo termina su anécdota y quieres devolverle la pregunta.', opts: ['Has that ever happened to you?', 'Did that ever happen you?', 'Has that ever happened you?'], a: 'Has that ever happened to you?', why: '<b>happen <u>to</u> someone</b>. Present perfect con <i>ever</i> para la experiencia.' },
          { q: 'Quieres contar una experiencia parecida a la suya.', opts: ['I had a similar experience once…', 'I have a similar experience once…', 'I had a same experience once…'], a: 'I had a similar experience once…', why: '<b>I had a similar experience once</b>: pasado simple + <i>once</i>.' },
          { q: 'Su historia te recuerda a otra tuya y la enganchas.', opts: ["That's like the time that I lost my passport in Rome.", "That's like the time what I lost my passport in Rome.", "That's as the time that I lost my passport in Rome."], a: "That's like the time that I lost my passport in Rome.", why: '<b>That\'s like the time (that)…</b> <i>Like</i> + sustantivo; <i>that</i> o nada, nunca <i>what</i>.' },
          { q: 'Vas a contar una anécdota que te vino a la cabeza.', opts: ['That reminds me of a story.', 'That remembers me a story.', 'That reminds me a story.'], a: 'That reminds me of a story.', why: '<b>remind someone of</b> something. Sin <i>of</i> significa "recordarle a alguien que haga algo".' },
          { q: 'Alguien te pregunta si recuerdas un viaje inolvidable. Respondes que es imposible olvidarlo.', opts: ['How could I forget?', "I don't recall.", 'That rings a bell.'], a: 'How could I forget?', why: '<b>How could I forget?</b> = ¿cómo olvidarlo?' },
          { q: 'Tu amiga insiste en que estuviste en esa fiesta y tú de verdad no lo crees.', opts: ["I don't think so. I was in Chile that month.", "I don't think it. I was in Chile that month.", "I think that no. I was in Chile that month."], a: "I don't think so. I was in Chile that month.", why: '<b>I don\'t think so</b>: <i>so</i> sustituye a la cláusula entera.' },
        ] },
        { label: 'Responde recordando', type: 'soft', eyebrow: 'Recalling and sharing · escritura', title: 'Responde con la frase de la unidad que pide la situación', explain: 'Lee lo que te dicen y responde con una frase de la unidad: <b>That rings a bell</b> · <b>It\'s all coming back to me now</b> · <b>I don\'t recall…</b> · <b>That whole period\'s a bit vague</b> · <b>Has that ever happened to you?</b> · <b>I had a similar experience once…</b> · <b>That\'s like the time that…</b> · <b>That reminds me of a story…</b> · <b>Don\'t tell me you don\'t remember</b> · <b>Do you remember that time we…?</b> Añade una frase más si quieres.', missing: 'Falta una frase de la unidad: <i>That rings a bell · It\'s all coming back to me now · I don\'t recall · a bit vague · Has that ever happened to you? · I had a similar experience once · That\'s like the time · That reminds me of · Don\'t tell me you don\'t remember · Do you remember that time…</i>', pattern: /\b(?:that rings a bell|it['’]s all coming back to me|i don['’]t recall|a bit vague|don['’]t tell me you don['’]t remember|do you remember that time|has that ever happened to you|i had a similar experience|that['’]s like the time|that reminds me of)\b/, items: [
          { h: '"We met at the conference in 2019, remember? The one in Arequipa." (te suena, pero no estás seguro)', a: 'That rings a bell. Was that the conference with the terrible coffee?' },
          { h: '"You were the guy who fell asleep during the keynote!" (ahora sí lo recuerdas todo)', a: "Oh no. It's all coming back to me now. I had worked all night." },
          { h: '"Didn\'t you say you would send me the photos?" (no lo recuerdas, con educación)', a: "I don't recall saying that, but I'll send them today." },
          { h: '"What was our history teacher\'s name in second grade?" (esa época la tienes borrosa)', a: "That whole period's a bit vague, honestly. Mrs. Flores?" },
          { h: '"I once got on the wrong bus and ended up in another city." (quieres contar algo parecido)', a: "I had a similar experience once. I took a bus to Ica instead of Chincha." },
          { h: '"My phone died right before an important call." (enganchas con tu anécdota)', a: "That's like the time that my laptop died in the middle of a demo." },
          { h: 'Tu amigo cuenta que perdió las llaves tres veces en una semana. (terminas tu historia y le devuelves la pregunta)', a: 'Has that ever happened to you on a trip? I lost mine in Santiago.' },
          { h: 'Hablan de olores de la infancia y te viene una historia a la cabeza.', a: 'That reminds me of a story about my grandmother and a very stinky cheese.' },
          { h: 'Un antiguo compañero de la universidad te mira sin reconocerte. (provócalo)', a: "Don't tell me you don't remember me! We sat together for two years." },
          { h: 'Quieres que tu prima recuerde el verano en que se perdieron en la playa.', a: 'Do you remember that time we got lost on the beach in Viña?' },
        ] },
        { label: 'Role-play', type: 'roleplay', eyebrow: 'Role-play con ramas', title: 'El reencuentro', intro: 'Renato, tu compañero de universidad, te reconoce en una boda diez años después. Tú no lo ubicas de inmediato. Reconócelo con elegancia, recuerda las anécdotas (aunque algunas estén borrosas), comparte una experiencia parecida y cuéntale qué haces ahora. Si cortas sus historias o dices "no me acuerdo de nada", la escena se enfría.', scenes: [
          { t: 'El reencuentro en la boda', you: 'Aldo, el invitado que no ubica a nadie', partner: 'Renato', role: 'tu compañero de universidad, que no ves desde hace diez años', goal: 'Reconócelo, recuerda las anécdotas con las frases de la unidad (aunque estén borrosas), comparte una experiencia parecida y cierra contando qué haces ahora con una frase enfática.', start: 'a', nodes: {
            a: { say: "Aldo? Aldo! Don't tell me you don't remember me!", opts: [
              { t: "Renato! Of course! Sorry, I didn't recognize you with the beard.", ok: 2, why: 'Lo reconoces por el nombre y te disculpas con el verbo exacto: <b>recognize</b> = reconocer a alguien al verlo.', next: 'b' },
              { t: "Renato! Wow, it's been ages. You look different.", ok: 1, why: 'Correcta y natural (<i>it\'s been ages</i>). Un poco vaga: no explicas por qué dudaste.', next: 'b' },
              { t: "Sorry, I don't remember of you.", ok: 0, why: '<b>remember</b> va sin <i>of</i>: <i>I don\'t remember you</i>. Y decirlo así, sin suavizar, enfría el reencuentro.', next: 'a2' },
            ] },
            a2: { say: "Ouch. We sat together in Professor Vega's database class for two years!", opts: [
              { t: "Database class… that rings a bell! Renato! It's all coming back to me now.", ok: 2, why: 'Las dos frases de la unidad en orden natural: primero <b>That rings a bell</b> (me suena) y luego <b>It\'s all coming back to me now</b> (ya me acuerdo).', next: 'b' },
              { t: "Oh yes, now I remember you. Renato, right?", ok: 1, why: 'Correcta. Funciona, pero <i>now I remember</i> es más plano que <i>It\'s all coming back to me now</i>.', next: 'b' },
              { t: "No, I don't recall nothing about that class.", ok: 0, why: 'Doble negación: <b>I don\'t recall anything</b>. Y seguir negando lo deja sin salida; mejor <i>That rings a bell…</i>', next: 'b' },
            ] },
            b: { say: "Do you remember that time we stayed all night finishing the final project and the lab lost power at 5 a.m.?", opts: [
              { t: "How could I forget? I have a vivid memory of your face when the screen went black.", ok: 2, why: '<b>How could I forget?</b> + <b>a vivid memory of</b> + detalle. Así se responde a <i>Do you remember that time…?</i>', next: 'c' },
              { t: "Yes, I remember that. We lost everything.", ok: 1, why: 'Correcta pero corta. Un detalle sensorial o una frase de la unidad la haría más viva.', next: 'c' },
              { t: "That whole period's a bit vague, honestly. I don't remember anything.", ok: 0, why: 'La frase es correcta (<i>a bit vague</i>), pero rematar con <i>I don\'t remember anything</i> cierra la puerta a la historia que él quiere contar.', next: 'c2' },
            ] },
            c2: { say: "Really? You don't remember the power cut? You almost cried, man!", opts: [
              { t: "Wait… it's all coming back to me now. We had to redo the whole database in three hours!", ok: 2, why: 'Rescatas la conversación con <b>It\'s all coming back to me now</b> y añades un detalle: eso es lo que la otra persona espera.', next: 'd' },
              { t: "OK, that rings a bell. Something about redoing the project?", ok: 1, why: 'Correcta: <b>That rings a bell</b> + pregunta para que él complete. Algo tibia, pero funciona.', next: 'd' },
              { t: "No. Anyway, what do you do now?", ok: 0, why: 'Cortas su historia y cambias de tema. En un reencuentro eso es casi una grosería; la unidad te da <i>That rings a bell</i> justo para no hacer esto.', next: 'fail' },
            ] },
            c: { say: "And the smell of that lab! Burned coffee and old computers.", opts: [
              { t: "That musty smell! The thing I remember most is the coffee machine that never worked.", ok: 2, why: 'Adjetivo de los sentidos (<b>musty</b>) y frase enfática (<b>The thing I remember most is…</b>) con <i>is</i> bien concordado.', next: 'd' },
              { t: "Yes, it smelled terrible. I remember the coffee machine.", ok: 1, why: 'Correcta. <i>Terrible</i> es genérico; <i>musty</i> o <i>stinky</i> pintan mejor la escena.', next: 'd' },
              { t: "That smell reminds me the coffee machine.", ok: 0, why: 'Falta la preposición: <b>reminds me of</b> the coffee machine.', next: 'd' },
            ] },
            d: { say: "Anyway, last month I lost a whole day of work because I forgot to save a file. Has that ever happened to you?", opts: [
              { t: "Has it ever! I had a similar experience once: a deployment on a Friday, and the backup was empty.", ok: 2, why: '<b>I had a similar experience once</b> es la frase para compartir, y <i>Has it ever!</i> es la reacción enfática natural a <i>Has that ever happened to you?</i>', next: 'e' },
              { t: "Yes, many times. Last year I lost a report.", ok: 1, why: 'Correcta y breve. Con <i>That\'s like the time that…</i> o <i>I had a similar experience once</i> engancharías mejor la historia.', next: 'e' },
              { t: "Yes, it happened me once with a report.", ok: 0, why: '<b>happen <u>to</u> me</b>: <i>it happened to me once</i>.', next: 'e' },
            ] },
            e: { say: "Ha! So, what do you do now? Still coding?", opts: [
              { t: "Still coding, at a bank. But what I really love these days is my little food business on weekends.", ok: 2, why: 'Frase enfática de la unidad (<b>what I really love… is…</b>) para destacar lo que importa, con <i>is</i> singular.', next: 'win' },
              { t: "Yes, I work at a bank. And I have a food business too.", ok: 1, why: 'Correcta pero plana: dos datos sin énfasis. La unidad te da <i>What I love is…</i> para que se note qué te importa.', next: 'win' },
              { t: "Yes, I'm coding. What I love it is my food business.", ok: 0, why: 'No repitas el objeto: <b>What I love is</b> my food business, sin <i>it</i>.', next: 'meh' },
            ] },
            win: { say: "A food business! That reminds me of a story... but let's get a drink first. It's so good to see you, man.", end: true, outcome: 'win', note: 'Reconociste a Renato (<b>recognize</b>), recordaste con las frases de la unidad (<b>That rings a bell</b>, <b>It\'s all coming back to me now</b>, <b>How could I forget?</b>), describiste con los sentidos (<b>musty</b>), compartiste una experiencia (<b>I had a similar experience once</b>) y cerraste con énfasis (<b>What I really love is…</b>).' },
            meh: { say: "Nice! Well, let's grab a drink and you tell me about it.", end: true, outcome: 'meh', note: 'Buen reencuentro, pero la última frase tenía el error típico de la frase enfática: <s>What I love it is</s> → <b>What I love is</b>. Renato ni lo notó; un nativo sí.' },
            fail: { say: "Right. Well... nice to see you, Aldo. I think I see someone I know over there.", end: true, outcome: 'fail', note: 'Negaste recordar y después cortaste su historia. En un reencuentro, aunque la época esté borrosa, se juega con <b>That rings a bell</b> → pregunta → <b>It\'s all coming back to me now</b>. Y se comparte: <b>I had a similar experience once…</b>' },
          } },
        ] },
      ] },
    ],
  };
})();
